    assert!(reg.request_changes(&g.id, &t.id, "   ").is_err());
    let after = reg.request_changes(&g.id, &t.id, "retries still leak a handle").unwrap();
    // Status stays at the gate (orchestrator re-dispatches); findings recorded.
