#[test]
fn rename_precedence_human_beats_orchestrator_beats_default() {
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
    let w = reg.spawn_agent(&g.id, Role::Worker, "", "t", false, None).unwrap();
    // Starts at the id-derived default.
    let seq = w.id.rsplit('-').next().unwrap().to_string();
    assert_eq!(w.name, format!("worker {seq}"));

    // Orchestrator outranks the default → applies.
    reg.rename_agent(&w.id, "w: parser", NameSource::Orchestrator).unwrap();
    assert_eq!(reg.agent(&w.id).unwrap().name, "w: parser");

    // Human outranks the orchestrator → applies and locks.
    reg.rename_agent(&w.id, "my parser work", NameSource::Human).unwrap();
    assert_eq!(reg.agent(&w.id).unwrap().name, "my parser work");

    // A later orchestrator rename must NOT override the human's title.
    let err = reg.rename_agent(&w.id, "w: something else", NameSource::Orchestrator).unwrap_err();
    assert!(err.contains("human"), "rejection must explain the precedence: {err}");
    assert_eq!(
        reg.agent(&w.id).unwrap().name,
        "my parser work",
        "human rename must survive a later orchestrator rename"
    );

    // The human can still re-rename their own pane (human ≥ human).
    reg.rename_agent(&w.id, "parser v2", NameSource::Human).unwrap();
    assert_eq!(reg.agent(&w.id).unwrap().name, "parser v2");
}

#[test]
fn rename_strips_control_characters() {
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
    let w = reg.spawn_agent(&g.id, Role::Worker, "", "t", false, None).unwrap();
    // A pasted name can't smuggle newlines/escape codes into the title/roster.
    let applied = reg.rename_agent(&w.id, "w-2:\tgit\nfix\u{1b}[31m", NameSource::Orchestrator).unwrap();
    assert_eq!(applied, "w-2:gitfix[31m");
    assert!(!applied.chars().any(|c| c.is_control()));
    // An all-control name is rejected, not silently applied as empty.
    assert!(reg.rename_agent(&w.id, "\u{1b}\n\t", NameSource::Orchestrator).is_err());
}

#[test]
fn roster_persists_the_name_source_tier() {
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
    let w = reg.spawn_agent(&g.id, Role::Worker, "", "t", false, None).unwrap();
    // A human rename must persist its tier, not just the text, so a later
    // rejoin can restore the "human wins" guarantee (#95r).
    reg.rename_agent(&w.id, "my parser work", NameSource::Human).unwrap();
    let roster: Value =
        serde_json::from_str(&fs::read_to_string(reg.state_root().join(&g.id).join("agents.json")).unwrap())
            .unwrap();
    let row = roster.as_array().unwrap().iter().find(|r| r["id"] == w.id.as_str()).unwrap();
    assert_eq!(row["name"], "my parser work");
    assert_eq!(row["name_source"], "human", "the tier must be durable, got: {row}");
}

#[test]
fn rejoined_session_restores_the_human_name_tier() {
    use loomux_lib::orchestration::resume_recorded_session;
    use std::sync::Arc;
    let dir = tempfile::tempdir().unwrap();
    // A REAL directory (#412) — see the comment in
    // `worker_session_rejoin_requires_live_group_then_reuses_session`.
    let repo = tempfile::tempdir().unwrap();
    let repo_path = repo.path().to_string_lossy().into_owned();
    let reg = Arc::new(relaunch_registry(dir.path()));
    reg.set_port(45999);
    let g = reg.create_group(&repo_path, rails()).unwrap();
    let orch = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    let w = reg.spawn_agent(&g.id, Role::Worker, "", "t", false, None).unwrap();
    let sid = w.session_id.clone().unwrap();
    // Human renames the pane, then it dies (pre-"restart").
    reg.rename_agent(&w.id, "my parser work", NameSource::Human).unwrap();
    reg.mark_dead(&w.id, Some(0));

    // Rejoin (background spawn) must come back at the human tier, not demoted
    // to orchestrator — otherwise the "human wins" guarantee dies on restart.
    assert!(resume_recorded_session(&reg, &sid, None, false).unwrap().is_none());
    let deadline = std::time::Instant::now() + Duration::from_secs(3);
    let rejoined_id = loop {
        let hit = reg
            .list_agents(&g.id)
            .as_array()
            .unwrap()
            .iter()
            .find(|a| a["session"] == sid.as_str() && a["status"] == "running")
            .map(|a| a["id"].as_str().unwrap().to_string());
        if let Some(id) = hit {
            break id;
        }
        assert!(std::time::Instant::now() < deadline, "rejoin did not complete");
        std::thread::sleep(Duration::from_millis(50));
    };
    assert_ne!(rejoined_id, w.id, "rejoin mints a fresh id");
    assert_eq!(reg.agent(&rejoined_id).unwrap().name, "my parser work", "name restored");

    // The orchestrator cannot clobber the restored human name.
    let co = reg.resolve_token(&orch.token).unwrap();
    let r = dispatch(&reg, &co, "tools/call",
        &json!({ "name": "rename_agent", "arguments": { "agent_id": rejoined_id, "name": "w: something else" } }))
        .unwrap();
    assert_eq!(r["isError"], true, "orchestrator must not override a restored human rename");
    assert!(r["content"][0]["text"].as_str().unwrap().contains("human"));
    assert_eq!(reg.agent(&rejoined_id).unwrap().name, "my parser work");
}

// ---------- cost containment (#7): pause, idle-kill, spawn-rate, usage ----------

/// Guardrails with the two cost knobs set; other fields mirror `rails()`
/// but with a roomier agent cap so the spawn-rate guardrail can be exercised
/// without tripping the live-agent cap first.
fn costed_rails(idle_kill_minutes: u32, max_spawns_per_hour: u32) -> Guardrails {
    Guardrails {
        max_agents: 6,
        idle_kill_minutes,
        max_spawns_per_hour,
        ..rails()
    }
}

/// Guardrails with a watchdog stall window set (other fields mirror
/// `costed_rails`); a roomy agent cap so several workers can be watched.
fn watchdog_rails(watchdog_stall_minutes: u32) -> Guardrails {
    Guardrails { watchdog_stall_minutes, ..costed_rails(0, 0) }
}

#[test]
fn idle_should_kill_respects_threshold_and_disable() {
    let min = 60_000u64;
    // Disabled (0) never kills, no matter how long idle.
    assert!(!idle_should_kill(Some(0), 100 * min, 0));
    // An agent with work (None) is never idle-killed.
    assert!(!idle_should_kill(None, 100 * min, 5));
    // Under the threshold: safe. At/over: kill.
    assert!(!idle_should_kill(Some(0), 4 * min, 5));
    assert!(!idle_should_kill(Some(min), 5 * min, 5)); // exactly 4 min idle < 5
    assert!(idle_should_kill(Some(0), 5 * min, 5)); // exactly at threshold
    assert!(idle_should_kill(Some(0), 10 * min, 5));
}

#[test]
fn spawn_rate_exceeded_counts_only_the_trailing_window() {
    let window = 60 * 60 * 1000u64;
    let now = 10 * window; // 10h in
    // Unlimited (0) never trips.
    assert!(!spawn_rate_exceeded(&[now, now, now, now], now, 0, window));
    // Three within the last hour, limit 3 → next is refused.
    let recent = [now - 1000, now - 2000, now - 3000];
    assert!(spawn_rate_exceeded(&recent, now, 3, window));
    // The same three but limit 4 → still room.
    assert!(!spawn_rate_exceeded(&recent, now, 4, window));
    // Old spawns (outside the window) don't count toward the cap.
    let stale = [now - window - 1, now - 2 * window, now - 500];
    assert!(!spawn_rate_exceeded(&stale, now, 2, window));
}

#[test]
fn parse_session_cost_reads_the_lowest_statusline_dollar() {
    // Typical Claude statusline at the bottom of the pane.
    let pane = "some agent output\n$ ran a command\nmodel: sonnet · $0.42 · 12k tokens";
    assert_eq!(parse_session_cost(pane), Some(0.42));
    // Thousands separators tolerated; bottom-most render wins.
    assert_eq!(parse_session_cost("cost $1.00\ntotal $1,234.56 session"), Some(1234.56));
    // A bare "$" or "$." with no digits is not a cost.
    assert_eq!(parse_session_cost("price: $ TBD\nsee $.foo"), None);
    // No dollar figure at all.
    assert_eq!(parse_session_cost("just some\noutput lines"), None);
    // Whole-dollar amount.
    assert_eq!(parse_session_cost("session cost $3"), Some(3.0));
}

#[test]
fn pause_suppresses_delivery_and_persists_across_restart() {
    let dir = tempfile::tempdir().unwrap();
    let gid;
    {
        let reg = relaunch_registry(dir.path());
        reg.set_port(45999);
        let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
        gid = g.id.clone();
        let w = reg.spawn_agent(&g.id, Role::Worker, "w", "t", false, None).unwrap();
        // Not paused: delivery proceeds past the pause gate and only fails
        // because test mode has no real terminal.
        let err = reg.deliver_prompt(&w.id, "hello", "loomux", Delivery::MidSession).unwrap_err();
        assert!(err.contains("terminal"), "unpaused delivery must reach the pty step, got: {err}");
        // Paused: delivery is suppressed (Ok, no error) and audited.
        reg.pause_group(&g.id).unwrap();
        assert!(reg.is_paused(&g.id));
        reg.deliver_prompt(&w.id, "hello again", "loomux", Delivery::MidSession).unwrap();
        let log = fs::read_to_string(reg.state_root().join(&g.id).join("audit.jsonl")).unwrap();
        assert!(log.contains("prompt-suppressed-paused"), "suppression must be audited");
        assert!(reg.state_root().join(&g.id).join("paused").is_file(), "pause marker must be written");
    }
    // Restart: the pause survives (marker re-seeds the in-memory flag).
    let reg = relaunch_registry(dir.path());
    reg.set_port(45999);
    let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
    assert_eq!(g.id, gid);
    assert!(reg.is_paused(&g.id), "a paused group must stay paused across restarts");
    // Resume clears the flag and the marker.
    reg.resume_group(&g.id).unwrap();
    assert!(!reg.is_paused(&g.id));
    assert!(!reg.state_root().join(&g.id).join("paused").is_file(), "resume must remove the marker");
}

#[test]
fn idle_workers_are_reap_candidates_but_busy_ones_and_orchestrator_are_not() {
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", costed_rails(5, 0)).unwrap();
    reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    let idle = reg.spawn_agent(&g.id, Role::Worker, "idle", "", false, None).unwrap();
    let busy = reg.spawn_agent(&g.id, Role::Worker, "busy", "do work", false, None).unwrap();
    // Read the idle worker's stamped idle-since so the test is time-relative.
    let roster = reg.list_agents(&g.id);
    let idle_since = roster
        .as_array()
        .unwrap()
        .iter()
        .find(|a| a["id"] == idle.id.as_str())
        .and_then(|a| a["idle_since_ms"].as_u64())
        .expect("an idle-spawned worker must carry idle_since_ms");
    // The busy worker (spawned with a task) has no idle clock.
    let busy_idle = roster
        .as_array()
        .unwrap()
        .iter()
        .find(|a| a["id"] == busy.id.as_str())
        .unwrap()["idle_since_ms"]
        .clone();
    assert!(busy_idle.is_null(), "a worker given a task must not start the idle clock");
    let threshold_ms = 5 * 60_000u64;
    // Just before the threshold: nobody is reaped.
    let before = reg.idle_reap_candidates(idle_since + threshold_ms - 1);
    assert!(before.is_empty(), "must not reap before the timeout, got: {before:?}");
    // At/after the threshold: only the idle worker (never the orchestrator or
    // the busy worker).
    let after = reg.idle_reap_candidates(idle_since + threshold_ms);
    assert_eq!(after, vec![idle.id.clone()], "only the idle worker crosses the timeout");
}

#[test]
fn idle_kill_disabled_reaps_nothing() {
    let (reg, _d) = test_registry();
    // idle_kill_minutes = 0 → the guardrail is off.
    let g = reg.create_group("C:/tmp/repo", costed_rails(0, 0)).unwrap();
    reg.spawn_agent(&g.id, Role::Worker, "idle", "", false, None).unwrap();
    // Even absurdly far in the future, nothing is a candidate.
    assert!(reg.idle_reap_candidates(u64::MAX / 2).is_empty());
}

#[test]
fn reaper_spares_a_worker_reactivated_before_the_kill() {
    // Selection and kill happen under separate locks; a worker prompted in
    // that window (idle clock cleared) must not be reaped. reap_idle_agents
    // re-checks idle_should_kill immediately before killing.
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", costed_rails(5, 0)).unwrap();
    let orch = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    let idle = reg.spawn_agent(&g.id, Role::Worker, "idle", "", false, None).unwrap();
    let co = reg.resolve_token(&orch.token).unwrap();
    let far_future = u64::MAX / 2;
    // The idle worker is a genuine candidate at that time.
    assert_eq!(reg.idle_reap_candidates(far_future), vec![idle.id.clone()]);
    // The orchestrator hands it work — send_prompt clears its idle clock
    // (delivery then fails in test mode with no pane, which is fine).
    let _ = dispatch(&reg, &co, "tools/call",
        &json!({ "name": "send_prompt", "arguments": { "agent_id": idle.id, "text": "here is a task" } }));
    // Now it is no longer idle, so the reaper kills nothing.
    assert!(reg.reap_idle_agents(far_future).is_empty(),
        "a re-activated worker must not be reaped");
    // And it is still alive in the roster.
    let roster = reg.list_agents(&g.id).to_string();
    assert!(roster.contains(&idle.id));
}

#[test]
fn spawn_rate_guardrail_backstops_a_burst() {
    let (reg, _d) = test_registry();
    // Cap 2 spawns/hour, roomy agent cap so the rate limit is what bites.
    let g = reg.create_group("C:/tmp/repo", costed_rails(0, 2)).unwrap();
    reg.spawn_agent(&g.id, Role::Worker, "w1", "t", false, None).unwrap();
    reg.spawn_agent(&g.id, Role::Worker, "w2", "t", false, None).unwrap();
    let err = reg.spawn_agent(&g.id, Role::Worker, "w3", "t", false, None).unwrap_err();
    assert!(err.contains("spawn-rate"), "third spawn within the hour must be refused, got: {err}");
    // The orchestrator is exempt from the spawn-rate backstop.
    reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
}

#[test]
fn report_completion_reidles_worker_and_send_prompt_reactivates() {
    let (reg, _d, co, cw) = setup_mcp();
    // The worker from setup_mcp was spawned with a task → not idle.
    let idle_of = |id: &str| -> Value {
        reg.list_agents(&cw.group)
            .as_array()
            .unwrap()
            .iter()
            .find(|a| a["id"] == id)
            .unwrap()["idle_since_ms"]
            .clone()
    };
    assert!(idle_of(&cw.agent_id).is_null(), "a tasked worker is not idle");
    // Reporting done re-idles it (delivery to the orchestrator fails in test
    // mode with no pane, but the idle transition happens first).
    let _ = dispatch(&reg, &cw, "tools/call",
        &json!({ "name": "report", "arguments": { "status": "done", "summary": "PR up" } }));
    assert!(!idle_of(&cw.agent_id).is_null(), "a worker that reported done becomes idle again");
    // The orchestrator sending it a fresh prompt clears the idle clock.
    let _ = dispatch(&reg, &co, "tools/call",
        &json!({ "name": "send_prompt", "arguments": { "agent_id": cw.agent_id, "text": "next" } }));
    assert!(idle_of(&cw.agent_id).is_null(), "send_prompt must re-activate an idle worker");
}

// ---------- watchdog: stalled-agent detection (#10) ----------

/// A time far past any real `now_ms()` (year ~33658), so a `watchdog_tick` at
/// this instant is unambiguously past the stall window for an agent whose
/// clock was stamped at spawn/report with the real wall clock.
const FAR: u64 = 1_000_000_000_000_000;

/// Group with an orchestrator and one working (tasked) worker under a watchdog
/// with the given stall window (minutes). Returns (reg, tempdir, group, worker).
fn watchdog_setup(stall_min: u32) -> (OrchRegistry, tempfile::TempDir, String, String) {
    let (reg, dir) = test_registry();
    let g = reg.create_group("C:/tmp/repo", watchdog_rails(stall_min)).unwrap();
    reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    let w = reg.spawn_agent(&g.id, Role::Worker, "w", "do work", false, None).unwrap();
    (reg, dir, g.id, w.id)
}

#[test]
fn watchdog_should_notify_respects_threshold_anti_nag_and_disable() {
    let min = 60_000u64;
    // A 0 window disables the guardrail entirely.
    assert!(!watchdog_should_notify(0, 100 * min, 0, false));
    // Inside the window: not yet.
    assert!(!watchdog_should_notify(0, 4 * min, 5, false));
    // At and past the window: notify.
    assert!(watchdog_should_notify(0, 5 * min, 5, false), "exactly at the window notifies");
    assert!(watchdog_should_notify(0, 10 * min, 5, false));
    // Past the window but already notified: the anti-nag latch suppresses it.
    assert!(!watchdog_should_notify(0, 10 * min, 5, true), "one notice per stall");
}

#[test]
fn watchdog_flags_a_silent_worker_once_per_stall() {
    let (reg, _d, gid, wid) = watchdog_setup(5);
    let no_output = HashMap::new();
    // Long past the stall window with no output and no report → one notice.
    assert_eq!(reg.watchdog_tick(FAR, &no_output, &HashSet::new()), vec![wid.clone()],
        "a silent working agent must be flagged");
    let log = fs::read_to_string(reg.state_root().join(&gid).join("audit.jsonl")).unwrap();
    assert!(log.contains("watchdog-stall"), "the stall must be audited, got: {log}");
    // Anti-nag: still silent, but already notified for this same stall.
    assert!(reg.watchdog_tick(FAR + 60_000, &no_output, &HashSet::new()).is_empty(),
        "must not nag twice for one uninterrupted stall");
}

#[test]
fn watchdog_stall_resets_when_the_agent_produces_output() {
    let (reg, _d, _gid, wid) = watchdog_setup(5);
    let empty = HashMap::new();
    assert_eq!(reg.watchdog_tick(FAR, &empty, &HashSet::new()), vec![wid.clone()]);
    // The CLI emits output: a grown pty counter is activity — clock and latch
    // both reset, and this very tick must not also flag a stall.
    let grew: HashMap<String, u64> = [(wid.clone(), 1024u64)].into_iter().collect();
    assert!(reg.watchdog_tick(FAR, &grew, &HashSet::new()).is_empty(), "output growth is activity, not a stall");
    // No further growth; a whole fresh window elapses → a brand-new notice.
    let later = FAR + 5 * 60_000 + 1;
    assert_eq!(reg.watchdog_tick(later, &grew, &HashSet::new()), vec![wid.clone()],
        "a new stall after activity earns a new notice");
}

#[test]
fn watchdog_ignores_idle_dead_and_disabled_agents() {
    // A 0 stall window disables the watchdog for the whole group.
    let (off, _d0, _g0, _w0) = watchdog_setup(0);
    assert!(off.watchdog_tick(FAR, &HashMap::new(), &HashSet::new()).is_empty(),
        "stall window 0 disables the watchdog");
    // With the guardrail on, idle and dead agents are still out of scope: idle
    // is the reaper's concern, and a dead/reaped pane must never be nudged.
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo2", watchdog_rails(5)).unwrap();
    reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    reg.spawn_agent(&g.id, Role::Worker, "idle", "", false, None).unwrap();
    let dead = reg.spawn_agent(&g.id, Role::Worker, "dead", "work", false, None).unwrap();
    reg.mark_dead(&dead.id, Some(1));
    let flagged = reg.watchdog_tick(FAR, &HashMap::new(), &HashSet::new());
    assert!(flagged.is_empty(),
        "neither an idle nor a dead agent may be watchdog-flagged, got: {flagged:?}");
}

#[test]
fn watchdog_stays_quiet_for_a_paused_group() {
    let (reg, _d, gid, wid) = watchdog_setup(5);
    reg.pause_group(&gid).unwrap();
    assert!(reg.watchdog_tick(FAR, &HashMap::new(), &HashSet::new()).is_empty(),
        "a paused group's agents idle out on purpose — no watchdog notices");
    // Crucially, the one-notice budget must be intact: pausing must not have
    // burned the latch, so on resume the outstanding stall still earns its
    // first notice.
    reg.resume_group(&gid).unwrap();
    assert_eq!(reg.watchdog_tick(FAR, &HashMap::new(), &HashSet::new()), vec![wid.clone()],
        "resuming an unattended stall must still earn its first notice");
}

#[test]
fn watchdog_stall_resets_when_the_agent_reports_or_messages() {
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", watchdog_rails(5)).unwrap();
    reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    let w = reg.spawn_agent(&g.id, Role::Worker, "w", "work", false, None).unwrap();
    let cw = reg.resolve_token(&w.token).unwrap();
    // Stalled and flagged (anti-nag latch now set).
    assert_eq!(reg.watchdog_tick(FAR, &HashMap::new(), &HashSet::new()), vec![w.id.clone()]);
    // A progress report is a sign of life: it clears the latch (via re-idle
    // bookkeeping), so a later silence re-notifies. If the latch had NOT been
    // cleared this tick would be empty — that's the discriminator.
    let _ = dispatch(&reg, &cw, "tools/call",
        &json!({ "name": "report", "arguments": { "status": "progress", "summary": "still going" } }));
    assert_eq!(reg.watchdog_tick(FAR + 60_000, &HashMap::new(), &HashSet::new()), vec![w.id.clone()],
        "a report must reset the stall, then a later silence re-notifies");
    // A free-form message likewise counts as activity and clears the latch.
    let _ = dispatch(&reg, &cw, "tools/call",
        &json!({ "name": "message_orchestrator", "arguments": { "text": "checking in" } }));
    assert_eq!(reg.watchdog_tick(FAR + 120_000, &HashMap::new(), &HashSet::new()), vec![w.id.clone()],
        "a message must also reset the stall, then a later silence re-notifies");
}

// ---------- autonomous mode: idle-tick, toggles, budget (#83) ----------

/// An autonomous group with a live (Running, headless) orchestrator. Returns
/// (reg, tempdir, group id, orchestrator id). Autonomous mode is ON, so
/// `idle_tick_tick` considers it. Intake gate explicitly OPTED OUT
/// (`intake_poll_minutes: Some(0)`) — this helper exists to test the base
/// #83 idle-tick mechanism (quiet window, activity floor, latch, per-hour
/// cap) in isolation; a group that wants the #429 smart default or an
/// explicit cadence uses `autonomous_setup_with_gate` instead. Without this,
/// EVERY multi-tick test below would silently start exercising the intake
/// gate too the moment #429's smart default shipped, since `rails()`'s
/// unset `intake_poll_minutes` now means "on while autonomous," not "off".
fn autonomous_setup() -> (OrchRegistry, tempfile::TempDir, String, String) {
    let (reg, dir) = test_registry();
    let g = reg
        .create_group("C:/tmp/repo", Guardrails { intake_poll_minutes: Some(0), ..rails() })
        .unwrap();
    let o = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    reg.set_autonomous(&g.id, true).unwrap();
    (reg, dir, g.id, o.id)
}

/// Count audit entries whose action is exactly `action`. Matches the
/// quote-delimited JSON value so a prefix action (`autonomous-off`) doesn't also
/// count its superset (`autonomous-off-failed`).
fn audit_count(reg: &OrchRegistry, group: &str, action: &str) -> usize {
    fs::read_to_string(reg.state_root().join(group).join("audit.jsonl"))
        .unwrap_or_default()
        .matches(&format!("\"{action}\""))
        .count()
}

/// The parsed audit entries for one action, in order — for assertions about a
/// line's `detail` payload rather than merely how many lines exist.
fn audit_entries(reg: &OrchRegistry, group: &str, action: &str) -> Vec<Value> {
    fs::read_to_string(reg.state_root().join(group).join("audit.jsonl"))
        .unwrap_or_default()
        .lines()
        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
        .filter(|e| e["action"] == action)
        .collect()
}

/// A durable usage snapshot carrying `tokens` input tokens under a unique key, to
/// seed a group's lifetime spend without a real transcript.
fn seed_usage(reg: &OrchRegistry, group: &str, key: &str, tokens: u64) {
    reg.upsert_usage_snapshot(group, UsageSnapshot {
        key: key.to_string(),
        agent_id: format!("agent-{key}"),
        name: key.to_string(),
        role: "worker".to_string(),
        source: "transcript".to_string(),
        input_tokens: tokens,
        output_tokens: 0,
        cache_creation_tokens: 0,
        cache_read_tokens: 0,
        cost_usd: None,
        estimated: true,
        model: Some("claude-opus-4-8".to_string()),
        updated_ms: now_ms(),
    });
}

#[test]
fn idle_tick_should_fire_respects_threshold_latch_cap_and_skew() {
    let min = 60_000u64;
    let none: &[u64] = &[];
    // A 0 threshold disables the tick entirely.
    assert!(!idle_tick_should_fire(0, 100 * min, 0, false, none, 6));
    // Inside the window: not yet. At/past: fire.
    assert!(!idle_tick_should_fire(0, 14 * min, 15, false, none, 6));
    assert!(idle_tick_should_fire(0, 15 * min, 15, false, none, 6), "exactly at the window fires");
    assert!(idle_tick_should_fire(0, 30 * min, 15, false, none, 6));
    // The one-notice latch suppresses a re-fire until output growth clears it.
    assert!(!idle_tick_should_fire(0, 30 * min, 15, true, none, 6), "latched → no re-fire");
    // Per-hour cap: at the cap (6 ticks inside the trailing hour) the backstop
    // blocks even a legitimately-due tick; a stale timestamp outside the hour
    // doesn't count.
    let now = 100 * min;
    let at_cap: Vec<u64> = (0..6).map(|i| now - i * min).collect(); // 6 within the hour
    assert!(!idle_tick_should_fire(0, now, 15, false, &at_cap, 6), "per-hour cap is a hard backstop");
    let under_cap: Vec<u64> = (0..5).map(|i| now - i * min).collect();
    assert!(idle_tick_should_fire(0, now, 15, false, &under_cap, 6), "under the cap fires");
    let cap_0 = at_cap.clone();
    assert!(idle_tick_should_fire(0, now, 15, false, &cap_0, 0), "cap 0 = uncapped");
    // Clock skew: now before the quiet clock reads as zero elapsed, never a huge
    // interval that would spuriously fire.
    assert!(!idle_tick_should_fire(50 * min, 10 * min, 15, false, none, 6), "no underflow on skew");
}

#[test]
fn autonomy_budget_exhausted_rule() {
    // 0 budget = no cap, never exhausted.
    assert!(!autonomy_budget_exhausted(1_000_000, 0));
    // Under budget: fine. At/over: exhausted (inclusive boundary).
    assert!(!autonomy_budget_exhausted(499, 500));
    assert!(autonomy_budget_exhausted(500, 500), "exactly at budget suspends");
    assert!(autonomy_budget_exhausted(999, 500));
}

#[test]
fn idle_tick_fires_once_per_window_and_rearms_on_output() {
    let (reg, _d, gid, oid) = autonomous_setup();
    let empty = HashMap::new();
    // Output-quiet far past the window → exactly one tick, audited.
    assert_eq!(reg.idle_tick_tick(FAR, &empty, &empty), vec![oid.clone()],
        "an idle autonomous orchestrator must be idle-ticked");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 1, "the tick must be audited once");
    // Anti-nag: still quiet, already notified → no second tick.
    assert!(reg.idle_tick_tick(FAR + 60_000, &empty, &empty).is_empty(),
        "one tick per idle window");
    // The orchestrator produces output (it acted on the tick): clock + latch
    // both reset, and this very tick can't also fire.
    let grew: HashMap<String, u64> = [(oid.clone(), 4096u64)].into_iter().collect();
    assert!(reg.idle_tick_tick(FAR, &grew, &empty).is_empty(),
        "output growth is activity, not an idle window");
    // No further growth; a whole fresh window elapses → a brand-new tick.
    assert_eq!(reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &grew, &empty), vec![oid.clone()],
        "a new idle window after activity earns a new tick");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 2);
}

#[test]
fn idle_tick_skips_non_autonomous_group() {
    let (reg, _d) = test_registry();
    let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
    reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    // Autonomous mode never enabled → the loop must ignore the group wholesale.
    let empty = HashMap::new();
    assert!(reg.idle_tick_tick(FAR, &empty, &empty).is_empty(),
        "a group without autonomous mode is never idle-ticked");
    assert_eq!(audit_count(&reg, &g.id, "idle-tick"), 0);
}

#[test]
fn idle_tick_skips_paused_group_preserving_latch() {
    let (reg, _d, gid, oid) = autonomous_setup();
    let empty = HashMap::new();
    reg.pause_group(&gid).unwrap();
    assert!(reg.idle_tick_tick(FAR, &empty, &empty).is_empty(),
        "a paused autonomous group is not idle-ticked");
    // The one-notice latch must be intact: pausing must not have burned it, so on
    // resume the outstanding idle window still earns its first tick.
    reg.resume_group(&gid).unwrap();
    assert_eq!(reg.idle_tick_tick(FAR, &empty, &empty), vec![oid.clone()],
        "resuming a still-idle autonomous group earns its first tick");
}

#[test]
fn idle_tick_defers_on_recent_human_input() {
    let (reg, _d, _gid, oid) = autonomous_setup();
    let empty = HashMap::new();
    // #496: anchor the output-based baseline (`last_output_progress_ms`) at FAR
    // first, with a real output burst — otherwise this test's own FAR time-skip
    // (from the agent's real spawn-time baseline) would itself look like the
    // orchestrator had gone output-silent for eons, and the input-defer bound
    // below would fire immediately regardless of "just typed" input. Seeding a
    // real burst here is what a live group's spawn + first tick already does;
    // it isn't new test scaffolding for the bound, just making this test's
    // synthetic clock skip land at a realistic starting point.
    let grew: HashMap<String, u64> = [(oid.clone(), 4096u64)].into_iter().collect();
    assert!(reg.idle_tick_tick(FAR, &grew, &empty).is_empty(), "output growth resets the clock, not a tick");
    // Review fix (round 1, NB-1): the defer assert MUST land past the ordinary
    // 5-minute quiet threshold, or the assertion passes even with the input
    // fold deleted entirely — vacuous coverage of the exact property this test
    // exists to guard. 6 minutes is past the threshold (proving the FOLD, not
    // mere quiet-window timing, is what defers here) while still comfortably
    // inside the 15-minute input-defer bound (so this stays the ORDINARY
    // defer, not `idle_tick_input_defer_max_minutes` kicking in — that's the
    // separate `idle_tick_fires_despite_perpetual_input_after_bound` test).
    let just_typed: HashMap<String, u64> = [(oid.clone(), FAR + 6 * 60_000)].into_iter().collect();
    assert!(reg.idle_tick_tick(FAR + 6 * 60_000, &empty, &just_typed).is_empty(),
        "never tick while the human is actively steering the pane, even though 6 minutes of \
         output-quiet alone (> the 5m threshold) would otherwise have fired");
    // Once the human input recedes past the window (its timestamp stays put
    // while real time moves on), the tick fires again — still comfortably
    // inside the bound, so this is the ordinary quiet-window recovery, not
    // `idle_tick_input_defer_max_minutes` kicking in.
    assert_eq!(reg.idle_tick_tick(FAR + 6 * 60_000 + 5 * 60_000 + 1, &empty, &just_typed), vec![oid.clone()],
        "after the human-input window elapses, the idle tick resumes");
}

#[test]
fn idle_tick_fires_despite_perpetual_input_after_bound() {
    // #496 root cause 2/2 (the guarantee, not the mechanism): xterm's own
    // automatic replies to a copilot pane's terminal queries (OSC colour, DA,
    // DSR/CPR, focus reports) restamp `last_user_input_ms` to "now" on EVERY
    // scan, forever, with no human present and no real output ever following
    // (PR-A fixes that mechanism at the source). This test doesn't assume
    // which mechanism refreshes the clock — it simulates the WORST case any
    // such refresher produces: input recency that tracks `now` exactly, every
    // single tick, unboundedly. Without a bound, the fold in `idle_tick_tick`
    // would set `last_progress_ms` to `now` every call, so `now - last_progress_ms`
    // never reaches the threshold and the tick can never fire — the deadlock
    // the human reported (#496): nothing recovers the group but a physical Enter.
    let (reg, _d, gid, oid) = autonomous_setup();
    let empty = HashMap::new();
    let grew: HashMap<String, u64> = [(oid.clone(), 4096u64)].into_iter().collect();
    let base = FAR;
    // One real output burst anchors the output-based baseline both clocks now
    // share; `idle_tick_input_defer_max_minutes` clamps the input fold against
    // THIS timestamp (`last_output_progress_ms`), never against whatever the
    // input clock itself claims.
    assert!(reg.idle_tick_tick(base, &grew, &empty).is_empty(), "output growth resets the clock, not a tick");

    let min = 60_000u64;
    // Perpetual "input": every scan, `inputs` reports the input timestamp as
    // exactly `now` — unbroken, advancing recency with no real output ever
    // following (`grew` stays flat: no growth = no activity). Companion
    // property (the plan's edge case): input still legitimately defers WITHIN
    // the bound, so genuine human steering is unaffected — asserted for every
    // minute up to the 15-minute default bound.
    for minute in 1..=19u64 {
        let now = base + minute * min;
        let inputs: HashMap<String, u64> = [(oid.clone(), now)].into_iter().collect();
        assert!(reg.idle_tick_tick(now, &grew, &inputs).is_empty(),
            "perpetual input must still defer the tick before the bound is reached (minute {minute})");
    }
    // Default bound (15m, `DEFAULT_IDLE_TICK_INPUT_DEFER_MAX_MINUTES`) plus the
    // default quiet threshold (5m, `DEFAULT_IDLE_TICK_MINUTES`) elapses since
    // the last real output. Input is STILL arriving every scan, right up to
    // `now` — genuinely perpetual, never lapsing — yet the clamp caps how far
    // it can defer and the tick must fire anyway.
    let now = base + 20 * min;
    let inputs: HashMap<String, u64> = [(oid.clone(), now)].into_iter().collect();
    assert_eq!(reg.idle_tick_tick(now, &grew, &inputs), vec![oid.clone()],
        "the input-defer bound must make perpetual input non-absorbing — the tick must fire eventually");
    assert_eq!(audit_count(&reg, &gid, "idle-tick-input-defer-bound"), 1,
        "a tick that fires because of the bound must be audited with its own distinct reason");
}

#[test]
fn idle_output_activity_ignores_subfloor_repaint_growth() {
    // The repaint-tolerant quiet signal: only a burst >= floor counts as the
    // orchestrator working; sub-floor creep is idle repaint noise.
    let floor = 2048u64;
    // Boundary is a `>=`: floor-1 is noise, floor is activity (rev-59 pin).
    assert!(!idle_output_is_activity(0, 2047, floor), "one byte under the floor is still noise");
    assert!(idle_output_is_activity(0, 2048, floor), "exactly at the floor is activity");
    assert!(idle_output_is_activity(1_000, 10_000, floor));
    assert!(!idle_output_is_activity(0, 200, floor), "a 200-byte statusline repaint is noise");
    assert!(!idle_output_is_activity(5_000, 5_200, floor), "sub-floor creep is not work");
    assert!(!idle_output_is_activity(5_000, 5_000, floor), "no growth is not activity");
    assert!(!idle_output_is_activity(5_000, 10, floor), "a counter reset (pty swap) is not activity");
}

#[test]
fn default_activity_floor_clears_a_real_idle_repaint_frame() {
    // Justify the 2048-byte default from real data: a captured full idle Claude
    // Code input-box render (box-drawing + ANSI) is the largest idle repaint frame
    // we have, and it must sit comfortably under the floor so it reads as noise.
    // (No raw idle-pane byte *stream* is captured anywhere and spawning a live CLI
    // is forbidden, so this rendered-frame size is the honest available measurement;
    // the tunable floor is the runtime remedy for a chattier CLI.)
    let frame = FIX_IDLE_BOX.len() as u64;
    assert!(frame < 2048, "idle box render is {frame}B — must be under the 2048B default floor");
    assert!(frame * 4 < 2048, "with ~4x headroom for a richer statusline, got {frame}B");
}

#[test]
fn idle_tick_tolerates_repaint_noise_but_resets_on_real_output() {
    // Root cause (b) regression: an idle orchestrator that emits periodic sub-floor
    // repaints (statusline/spinner) kept `output_total` creeping, so treating any
    // growth as activity reset the quiet clock every time and the tick never fired.
    let (reg, _d, gid, oid) = autonomous_setup();
    let m = |total: u64| -> HashMap<String, u64> { [(oid.clone(), total)].into_iter().collect() };
    let none = HashMap::new();
    // Sub-floor repaint growth over time must NOT reset the quiet clock: the tick
    // still fires after the threshold.
    assert!(reg.idle_tick_tick(1_000, &m(500), &none).is_empty(), "an early sub-floor repaint is not a tick");
    assert_eq!(reg.idle_tick_tick(FAR, &m(900), &none), vec![oid.clone()],
        "repaint-only growth must not starve the tick — it fires after the threshold");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 1);
    // A REAL burst (>= floor) after the tick IS genuine activity: it resets the
    // clock and re-arms the latch, so this very pass can't fire.
    assert!(reg.idle_tick_tick(FAR, &m(5_000), &none).is_empty(),
        "a real output burst re-arms the latch and resets the clock");
    // No immediate re-fire right after real activity...
    assert!(reg.idle_tick_tick(FAR + 60_000, &m(5_000), &none).is_empty(),
        "no re-fire within the window after real output");
    // ...but after a fresh full (5-min) window of quiet — repaint noise tolerated —
    // it fires again.
    assert_eq!(reg.idle_tick_tick(FAR + 5 * 60_000 + 1, &m(5_000), &none), vec![oid.clone()],
        "a fresh threshold of quiet after activity earns a new tick");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 2);
}

#[test]
fn idle_tick_minutes_is_configurable_persisted_and_surfaced() {
    // Root cause (a) fix: the window is a live-adjustable per-group knob (default 5),
    // so the human can drop it to 1–2 min to verify quickly, and the panel can see it.
    let (reg, dir, gid, _oid) = autonomous_setup();
    assert_eq!(reg.autonomy_state(&gid)["idle_tick_minutes"].as_u64().unwrap(), 5,
        "shipped default window is 5 minutes");
    // Live-set to 2 min: applied, persisted to the live guardrail, surfaced, audited.
    assert_eq!(reg.set_idle_tick_minutes(&gid, 2).unwrap(), 2);
    assert_eq!(reg.group(&gid).unwrap().guardrails.idle_tick_minutes, 2);
    assert_eq!(reg.autonomy_state(&gid)["idle_tick_minutes"].as_u64().unwrap(), 2);
    assert_eq!(audit_count(&reg, &gid, "idle-tick-minutes-set"), 1);
    // 0 coerces to the default (never "off" — the marker is the switch); huge clamps.
    assert_eq!(reg.set_idle_tick_minutes(&gid, 0).unwrap(), 5);
    assert_eq!(reg.set_idle_tick_minutes(&gid, 100_000).unwrap(), 1440);
    assert!(reg.set_idle_tick_minutes("no-such-group", 5).is_err());
    // Observability while ON: quiet_secs + eligible_in_secs are live, and the
    // countdown never exceeds the window.
    reg.set_idle_tick_minutes(&gid, 5).unwrap();
    let st = reg.autonomy_state(&gid);
    assert!(st["quiet_secs"].as_u64().is_some(), "quiet_secs is live while autonomous is on");
    let eligible = st["eligible_in_secs"].as_u64().unwrap();
    assert!(eligible <= 5 * 60, "eligible_in_secs counts down within the window, got {eligible}");
    // Persisted across restart (live-set value wins over the launch default).
    let reg2 = relaunch_registry(dir.path());
    reg2.set_port(45999);
    reg2.create_group("C:/tmp/repo", rails()).unwrap();
    assert_eq!(reg2.group(&gid).unwrap().guardrails.idle_tick_minutes, 5,
        "a live-set window survives restart");
    // OFF: no live meter.
    reg.set_autonomous(&gid, false).unwrap();
    let off = reg.autonomy_state(&gid);
    assert!(off["quiet_secs"].is_null(), "no quiet meter while autonomous is off");
    assert!(off["eligible_in_secs"].is_null());
    assert_eq!(off["tick_status"], "off");
}

#[test]
fn idle_tick_input_defer_bound_defaults_floors_caps_and_persists() {
    // #496: 0 (unset) resolves to the 15-minute default (3x DEFAULT_IDLE_TICK_MINUTES).
    let g = Guardrails { idle_tick_minutes: 5, ..rails() }.clamped();
    assert_eq!(g.idle_tick_input_defer_max_minutes, 15, "0 (unset) resolves to the 15m default");

    // Floored at the group's own (already-normalized) tick window: the bound can
    // never be tighter than the ordinary threshold — that would let it fire the
    // tick BEFORE `idle_tick_minutes` itself ever would.
    let g = Guardrails { idle_tick_minutes: 20, idle_tick_input_defer_max_minutes: 5, ..rails() }.clamped();
    assert_eq!(g.idle_tick_input_defer_max_minutes, 20, "floored at idle_tick_minutes, never tighter");

    // Capped at 24h — the same ceiling `idle_tick_minutes` uses.
    let g = Guardrails { idle_tick_input_defer_max_minutes: 100_000, ..rails() }.clamped();
    assert_eq!(g.idle_tick_input_defer_max_minutes, 1440, "capped at 24h");

    // No live setter this round (see the field's own doc), but it is still a
    // persisted, hand-editable guardrail: written to group.json and honored on
    // reload — same precedent as `idle_tick_fallback_minutes`/`context_window_
    // tokens_override`.
    let (reg, dir) = test_registry();
    let g = reg
        .create_group("C:/tmp/repo", Guardrails { idle_tick_input_defer_max_minutes: 45, ..rails() })
        .unwrap();
    assert_eq!(g.guardrails.idle_tick_input_defer_max_minutes, 45, "an explicit in-range value is honored, unclamped");
    let body = fs::read_to_string(reg.state_root().join(&g.id).join("group.json")).unwrap();
    let v: Value = serde_json::from_str(&body).unwrap();
    assert_eq!(v["guardrails"]["idle_tick_input_defer_max_minutes"].as_u64().unwrap(), 45,
        "the field is written to group.json, not silently dropped");
    let reg2 = relaunch_registry(dir.path());
    reg2.set_port(45999);
    let (_, persisted) = reg2.load_group_file(&g.id).unwrap();
    assert_eq!(persisted.idle_tick_input_defer_max_minutes, 45, "round-trips through group.json on a fresh load");
}

#[test]
fn idle_tick_input_defer_bound_floor_survives_launcher_relaunch() {
    // Round-1 review fix (rev-23): `load_group_file` alone doesn't exercise the
    // bug — the defect was in `create_group_ex`'s `resumed` re-hydration branch,
    // which resolved an unset (0) bound straight to `DEFAULT_IDLE_TICK_INPUT_
    // DEFER_MAX_MINUTES` (15) WITHOUT the `idle_tick_minutes` floor `clamped()`
    // applies everywhere else. A group with a tick window above 15 minutes and
    // no explicit bound — i.e. EVERY group.json written before this PR, since
    // the field didn't exist — got a tighter bound on relaunch than on a fresh
    // launch, silently disagreeing with the field's own doc and this PR's
    // design note. This is the relaunch leg the persistence test above was
    // missing (mirrors `intake_gate_config_survives_launcher_relaunch`'s
    // restart-a-fresh-registry shape).
    let dir = tempfile::tempdir().unwrap();
    let gid;
    {
        let reg = relaunch_registry(dir.path());
        reg.set_port(45999);
        // idle_tick_minutes above the 15m default; the bound left UNSET (0) at
        // the call site.
        let g = reg.create_group("C:/tmp/repo", Guardrails { idle_tick_minutes: 30, ..rails() }).unwrap();
        assert_eq!(g.guardrails.idle_tick_input_defer_max_minutes, 30,
            "fresh create: an unset bound floors at the group's own 30m tick window, not the 15m default");
        gid = g.id.clone();
    }
    // Round-2 review fix (rev-23): a fresh `create_group` writes group.json
    // with the ALREADY-RESOLVED value (30, from `clamped()`), so without this
    // step the relaunch leg below would read `persisted == 30` and only ever
    // exercise the non-zero branch — the branch that was never broken. The
    // round-1 bug lived in the UNSET (`persisted == 0`) branch, which a
    // pre-#500 group.json hits because the key never existed. Strip the key
    // here so the file actually matches that shape and the relaunch leg below
    // exercises the branch the bug was in — a test that passed with the key
    // still present passed for the wrong reason (confirmed: it stayed green
    // with the round-1 defect restored).
    let path = dir.path().join(&gid).join("group.json");
    let mut v: Value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
    v["guardrails"].as_object_mut().unwrap().remove("idle_tick_input_defer_max_minutes");
    fs::write(&path, serde_json::to_string_pretty(&v).unwrap()).unwrap();
    // A fresh registry (app restart) + a launcher relaunch on the same repo,
    // with the launcher's bare defaults (`rails()`, no field for this at all):
    // the persisted `idle_tick_minutes` must resolve the SAME unset-bound
    // floor a fresh launch would give it.
    let reg = relaunch_registry(dir.path());
    reg.set_port(45999);
    let g = reg.create_group("C:/tmp/repo", rails()).unwrap();
    assert_eq!(g.id, gid, "restart resumes the same group");
    assert_eq!(g.guardrails.idle_tick_minutes, 30, "the tick window itself already survives relaunch");
    assert_eq!(g.guardrails.idle_tick_input_defer_max_minutes, 30,
        "resume: an unset bound must get the SAME floor clamped() applies on a fresh launch — never a bare 15 \
         that quietly promises less protection than the docs state for this group");
}

#[test]
fn idle_activity_floor_is_configurable_persisted_and_surfaced() {
    // rev-59 MODERATE: the activity floor is a live-tunable guardrail, not a bare
    // const — the runtime remedy if a chatty CLI's idle repaints exceed the default.
    let (reg, dir, gid, _oid) = autonomous_setup();
    assert_eq!(reg.autonomy_state(&gid)["idle_activity_floor_bytes"].as_u64().unwrap(), 2048,
        "shipped default floor is 2048 bytes");
    assert_eq!(reg.set_idle_activity_floor(&gid, 8192).unwrap(), 8192);
    assert_eq!(reg.group(&gid).unwrap().guardrails.idle_activity_floor_bytes, 8192);
    assert_eq!(reg.autonomy_state(&gid)["idle_activity_floor_bytes"].as_u64().unwrap(), 8192);
    assert_eq!(audit_count(&reg, &gid, "idle-activity-floor-set"), 1);
    // 0 → default; huge clamps to 1 MiB; unknown group errors.
    assert_eq!(reg.set_idle_activity_floor(&gid, 0).unwrap(), 2048);
    assert_eq!(reg.set_idle_activity_floor(&gid, 999_999_999).unwrap(), 1024 * 1024);
    assert!(reg.set_idle_activity_floor("no-such-group", 4096).is_err());
    // Persisted across restart (live value wins over the launch default).
    reg.set_idle_activity_floor(&gid, 4096).unwrap();
    let reg2 = relaunch_registry(dir.path());
    reg2.set_port(45999);
    reg2.create_group("C:/tmp/repo", rails()).unwrap();
    assert_eq!(reg2.group(&gid).unwrap().guardrails.idle_activity_floor_bytes, 4096,
        "a live-set activity floor survives restart");
}

#[test]
fn a_higher_activity_floor_treats_bigger_growth_as_noise() {
    // The floor actually governs the tick: raise it above a 5 KB burst and that
    // growth reads as repaint noise (doesn't reset the quiet clock), so the tick
    // still fires — while a burst >= the floor is activity and re-arms the latch.
    let (reg, _d, gid, oid) = autonomous_setup();
    reg.set_idle_activity_floor(&gid, 8192).unwrap();
    let m = |t: u64| -> HashMap<String, u64> { [(oid.clone(), t)].into_iter().collect() };
    let none = HashMap::new();
    assert!(reg.idle_tick_tick(1_000, &m(5_000), &none).is_empty());
    assert_eq!(reg.idle_tick_tick(FAR, &m(9_000), &none), vec![oid.clone()],
        "with an 8 KB floor, 4–5 KB growth is repaint noise and the tick still fires");
    assert!(reg.idle_tick_tick(FAR, &m(20_000), &none).is_empty(),
        "a growth >= the floor (11 KB) is activity and re-arms the latch");
}

// ---------- idle-tick intake gate (#332): host-side, zero-token pre-check ----------

/// An autonomous group with a caller-chosen `intake_poll_minutes` (tri-state:
/// `Some(n)` for an explicit cadence — `n == 0` is the explicit opt-out,
/// `n > 0` an explicit value — or `None` to exercise the #429 smart default,
/// which resolves to `DEFAULT_INTAKE_POLL_MINUTES` since this helper always
/// turns autonomous mode on) and a caller-chosen `fallback_minutes`. Returns
/// (reg, tempdir, group id, orchestrator id) — the same shape as `autonomous_setup`.
fn autonomous_setup_with_gate(intake_poll_minutes: Option<u32>, fallback_minutes: u32) -> (OrchRegistry, tempfile::TempDir, String, String) {
    let (reg, dir) = test_registry();
    let g = reg
        .create_group(
            "C:/tmp/repo",
            Guardrails { intake_poll_minutes, idle_tick_fallback_minutes: fallback_minutes, ..rails() },
        )
        .unwrap();
    let o = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    reg.set_autonomous(&g.id, true).unwrap();
    (reg, dir, g.id, o.id)
}

/// Whether `audit.jsonl` contains a line for `action` whose raw JSON also
/// contains `needle` — a coarser version of `audit_count` that lets a test
/// assert on the SHAPE of one entry (e.g. the skip reason, the intake summary
/// folded into an `idle-tick` entry) without parsing full JSON.
fn audit_line_contains(reg: &OrchRegistry, group: &str, action: &str, needle: &str) -> bool {
    fs::read_to_string(reg.state_root().join(group).join("audit.jsonl"))
        .unwrap_or_default()
        .lines()
        .any(|l| l.contains(&format!("\"{action}\"")) && l.contains(needle))
}

#[test]
fn intake_gate_skips_a_quiet_tick_then_fires_once_a_signal_lands() {
    // Gate ON, generous fallback (won't fire on its own inside this test).
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(Some(5), 180);
    let empty = HashMap::new();
    // Establish a reference fire point so the fallback isn't trivially due against
    // the unseeded (0) default — see `seed_idle_tick_last_fired`'s doc.
    reg.seed_idle_tick_last_fired(&gid, FAR);

    // Quiet window elapsed, nothing new, no other wake reason, fallback not due:
    // the tick must be SKIPPED, not fired — and the skip is audited with a reason.
    assert!(reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &empty, &empty).is_empty(),
        "nothing new + no other wake reason + fallback not due must SKIP, not fire");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 0, "a skip must never be counted as a fire");
    assert!(audit_line_contains(&reg, &gid, "idle-tick-skipped", "fallback"),
        "the skip must be audited with its reason, not silent");

    // The host-side poller finds something: seed the pending summary a real
    // `poll_intake` would have composed, then the NEXT quiet window must fire —
    // and the notice must carry the summary (folded into the audited entry).
    reg.seed_intake_pending(&gid, "issue #42 labeled agent-ready (\"Do the thing\")");
    assert_eq!(reg.idle_tick_tick(FAR + 2 * (15 * 60_000 + 1), &empty, &empty), vec![oid.clone()],
        "an intake signal must fire even though nothing else changed");
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "issue #42 labeled agent-ready"),
        "the fired tick's audit entry must carry what the intake poll found");
}

#[test]
fn intake_gate_fires_regardless_when_a_ci_watch_is_outstanding() {
    // The lost-notification-degrades-to-poll-on-sweep invariant (orchestrator.md):
    // an outstanding CI watch means the tick's fallback-sweep duty still has a job,
    // even with zero label/PR news.
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(Some(5), 180);
    reg.seed_idle_tick_last_fired(&gid, FAR);
    reg.register_notification(&gid, &oid, notify::Condition::PrChecks { pr: 7 }, "watch it".into(), 60).unwrap();

    let empty = HashMap::new();
    assert_eq!(reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &empty, &empty), vec![oid.clone()],
        "a pending notification must force a fire even with no intake signal");
}

#[test]
fn intake_gate_fires_regardless_when_a_watchdog_stall_is_unresolved() {
    let (reg, _d) = test_registry();
    let g = reg
        .create_group(
            "C:/tmp/repo",
            Guardrails { intake_poll_minutes: Some(5), idle_tick_fallback_minutes: 180, watchdog_stall_minutes: 10, ..rails() },
        )
        .unwrap();
    let oid = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap().id;
    reg.set_autonomous(&g.id, true).unwrap();
    reg.seed_idle_tick_last_fired(&g.id, FAR);
    // Drive a REAL watchdog stall on a worker in the same group — the gate reads
    // `AgentEntry.watchdog_notified`, not a test-only backdoor.
    reg.spawn_agent(&g.id, Role::Worker, "w", "do work", false, None).unwrap();
    let watch_set = std::collections::HashSet::new();
    let fired = reg.watchdog_tick(FAR, &HashMap::new(), &watch_set);
    assert!(!fired.is_empty(), "sanity: the worker must actually be flagged stalled");

    let empty = HashMap::new();
    assert_eq!(reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &empty, &empty), vec![oid.clone()],
        "an unresolved watchdog stall must force a fire even with no intake signal");
}

#[test]
fn intake_gate_fallback_fires_unconditionally_once_it_comes_due() {
    // No intake signal, no pending notification, no watchdog stall — but enough
    // real time has passed since the last fire that the bounded fallback covers it,
    // so a poller bug (or a permanently-quiet group) can never silence the tick.
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(Some(5), 30); // 30 min = the floor
    reg.seed_idle_tick_last_fired(&gid, FAR);
    let empty = HashMap::new();

    // Just under the fallback: still skipped.
    assert!(reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &empty, &empty).is_empty());
    // Past the fallback (30 min since the seeded last-fire): fires even with
    // nothing new.
    assert_eq!(reg.idle_tick_tick(FAR + 30 * 60_000 + 1, &empty, &empty), vec![oid.clone()],
        "the bounded fallback must fire regardless once its own interval elapses");
}

#[test]
fn intake_gate_off_fires_unconditionally_exactly_like_before_332() {
    // #429 reversed the migration-safety default (absent/None now smart-
    // defaults ON while autonomous — see the next test), but the explicit
    // opt-out must still work exactly like the pre-#429 "off" behavior for an
    // operator who deliberately wants the polling load off: `Some(0)` is that
    // explicit opt-out, distinct from `None`.
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(Some(0), 30);
    let empty = HashMap::new();
    assert_eq!(reg.idle_tick_tick(FAR, &empty, &empty), vec![oid.clone()],
        "gate OFF must fire unconditionally, matching pre-#332 behavior");
    assert!(!audit_line_contains(&reg, &gid, "idle-tick-skipped", "fallback"),
        "a disabled gate must never produce a skip");
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "\"gate_enabled\":false"),
        "a bypass fire (gate off) must be observably distinct from a gated fire — the #429 \
         benchtest finding was exactly that these two looked identical in the audit log");
}

// ---------- #429 benchtest follow-up: suppressed/heartbeat observability ----------
//
// rev-95's live testbed run (loomux-testbed-cc077f09) showed six idle ticks in a row,
// each with `intake_summary: null`, EVERY one still delivering the full generic wake
// prompt — "the gate computes but does not gate". The gate's actual fire/skip DECISION
// was already correct (proved by the suite above); what was missing is that a skip, a
// real-signal fire, and a fallback-only fire were audited identically, so nobody could
// tell them apart after the fact. These tests pin the three new audit fields
// (`suppressed`, `heartbeat`, `gate_enabled`) that make the three cases distinguishable,
// and the transition/consecutive-tick shapes the fix brief asked for directly.

#[test]
fn intake_gate_null_intake_is_suppressed_and_audited() {
    let (reg, _d, gid, _oid) = autonomous_setup_with_gate(Some(5), 180); // generous fallback
    reg.seed_idle_tick_last_fired(&gid, FAR);
    let empty = HashMap::new();

    assert!(reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &empty, &empty).is_empty(),
        "null intake + no other reason must suppress, not deliver");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 0, "a suppressed tick is never counted as a fire");
    assert!(audit_line_contains(&reg, &gid, "idle-tick-skipped", "\"suppressed\":true"),
        "a suppressed tick must be observably marked, not just implied by the action name");
}

#[test]
fn intake_gate_heartbeat_fires_after_consecutive_suppressed_ticks() {
    // intake_minutes=10, fallback=30 → the bounded backstop comes due after exactly 2
    // consecutive suppressed ticks (each skip re-arms the gate 10 minutes out), proving
    // "after N consecutive suppressed ticks, deliver a real wake anyway" against the
    // ACTUAL per-tick cadence rather than one big wall-clock jump.
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(Some(10), 30);
    reg.seed_idle_tick_last_fired(&gid, FAR);
    let empty = HashMap::new();

    let tick1 = FAR + 15 * 60_000 + 1;
    assert!(reg.idle_tick_tick(tick1, &empty, &empty).is_empty(), "1st consecutive suppressed tick");
    let tick2 = tick1 + 10 * 60_000;
    assert!(reg.idle_tick_tick(tick2, &empty, &empty).is_empty(), "2nd consecutive suppressed tick");
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 0, "still nothing but suppressions so far");

    let tick3 = tick2 + 10 * 60_000;
    assert_eq!(reg.idle_tick_tick(tick3, &empty, &empty), vec![oid.clone()],
        "the bounded fallback must deliver a real wake once it comes due, even with nothing new — \
         a gate bug (or a genuinely quiet group) must never silence the orchestrator forever");
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "\"heartbeat\":true"),
        "a fallback-only fire must be marked as a heartbeat, distinct from a real signal");
}

#[test]
fn intake_gate_transition_from_suppressed_to_signal_fires_immediately_with_summary_embedded() {
    // (null, null, intake) → the signal must fire on the very next eligible tick, not
    // wait for the heartbeat's consecutive-tick count — a fresh signal is never held
    // hostage by the backstop timer just because prior ticks were suppressed.
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(Some(10), 180); // generous fallback: won't fire on its own
    reg.seed_idle_tick_last_fired(&gid, FAR);
    let empty = HashMap::new();

    let tick1 = FAR + 15 * 60_000 + 1;
    assert!(reg.idle_tick_tick(tick1, &empty, &empty).is_empty(), "1st: null intake, suppressed");
    let tick2 = tick1 + 10 * 60_000;
    assert!(reg.idle_tick_tick(tick2, &empty, &empty).is_empty(), "2nd: null intake, suppressed");

    reg.seed_intake_pending(&gid, "issue #77 labeled agent-ready (\"Fix the thing\")");
    let tick3 = tick2 + 10 * 60_000;
    assert_eq!(reg.idle_tick_tick(tick3, &empty, &empty), vec![oid.clone()],
        "a fresh intake signal must fire immediately, not wait out the fallback window");
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "issue #77 labeled agent-ready"),
        "the delivered notice must carry the summary so the orchestrator acts on it directly");
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "\"heartbeat\":false"),
        "a real-signal fire must never be mistaken for a heartbeat");
}

#[test]
fn intake_gate_smart_default_activates_while_autonomous_and_reproduces_the_benchtest_scenario() {
    // User-directed fix (option 1): the gate must be ON by default the moment a group is
    // autonomous, with NO config at all — `intake_poll_minutes: None`. This end-to-end
    // reproduction pins the actual reported shape: `loomux-testbed-cc077f09` logged SIX
    // idle ticks in a row with `intake_summary: null`, every one still delivering a wake.
    // On this fix, the same six null ticks must now be suppressed (zero wake prompts,
    // `suppressed:true` each time) and only the 7th — the bounded heartbeat — delivers.
    let (reg, _d, gid, oid) = autonomous_setup_with_gate(None, 45); // smart default cadence (5 min) x fallback
    reg.seed_idle_tick_last_fired(&gid, FAR);
    let empty = HashMap::new();

    let mut now = FAR + 15 * 60_000 + 1;
    for i in 1..=6 {
        assert!(reg.idle_tick_tick(now, &empty, &empty).is_empty(),
            "consecutive suppressed tick {i}/6 — no config was set, only autonomous mode");
        now += 5 * 60_000; // DEFAULT_INTAKE_POLL_MINUTES, smart-defaulted with no config at all
    }
    assert_eq!(audit_count(&reg, &gid, "idle-tick"), 0,
        "zero wake prompts delivered across all six null-intake ticks — this is the exact \
         benchtest finding, now fixed");
    assert_eq!(audit_count(&reg, &gid, "idle-tick-skipped"), 6);

    assert_eq!(reg.idle_tick_tick(now, &empty, &empty), vec![oid.clone()],
        "the 7th tick is the bounded heartbeat — a gate bug (or a genuinely quiet group) must \
         never silence the orchestrator forever, even under the smart default");
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "\"heartbeat\":true"));
    assert!(audit_line_contains(&reg, &gid, "idle-tick", "\"gate_enabled\":true"),
        "the smart default counts as the gate being genuinely engaged, not the legacy bypass");
}

#[test]
fn intake_gate_skip_for_one_group_never_starves_another_groups_tick_in_the_same_scan() {
    // rev-31 finding 2 (#329 coexistence seam), written while #329 was still not
    // in this tree: `idle_tick_tick` scans every autonomous orchestrator in ONE
    // pass, and any other per-tick mechanism sharing this loop needs a SKIP
    // decision for one agent to have ZERO effect on any other agent processed in
    // the same call. A gated-and-skipped group and a plain (gate-off) group,
    // ticked in the SAME `idle_tick_tick` call, must each resolve independently
    // — the skip must never short-circuit the scan. See the test right below
    // for the direct #329 cross-feature check, now that #329 has landed and
    // `compact_nudge_tick` is real code in this tree, not a description of one.
    let (reg, _d, gid_gated, _oid_gated) = autonomous_setup_with_gate(Some(5), 180);
    reg.seed_idle_tick_last_fired(&gid_gated, FAR);
    // #429: `rails()`'s default `intake_poll_minutes: None` now smart-defaults ON the
    // moment a group is autonomous — so "plain, gate OFF" needs an EXPLICIT opt-out
    // (`Some(0)`) to keep meaning what this test's comment says, instead of silently
    // also becoming a gated group via the new default.
    let g2 = reg
        .create_group("C:/tmp/repo-plain", Guardrails { intake_poll_minutes: Some(0), ..rails() })
        .unwrap(); // gate explicitly OFF
    let oid_plain = reg.spawn_agent(&g2.id, Role::Orchestrator, "orch2", "", false, None).unwrap().id;
    reg.set_autonomous(&g2.id, true).unwrap();

    let empty = HashMap::new();
    let fired = reg.idle_tick_tick(FAR + 15 * 60_000 + 1, &empty, &empty);
    assert_eq!(fired, vec![oid_plain.clone()],
        "the gated group must skip (nothing new) while the plain group in the SAME scan still \
         fires unconditionally — one group's skip must never starve another's tick");
}

#[test]
fn intake_gate_skip_never_starves_a_coexisting_compact_nudge_for_the_same_agent() {
    // rev-31 finding 2, re-verified against #329's ACTUAL final shape (now
    // merged): compact-nudge is NOT woven into `idle_tick_tick` at all — it is
    // its own background thread/function (`start_compact_nudge` /
    // `run_compact_nudge` / `compact_nudge_tick`) with its own anti-nag latch
    // (`compact_nudge_notified`) and its own output baseline
    // (`compact_nudge_last_output_total`, deliberately separate from this
    // gate's `last_output_total` — see that field's doc for the rev-24 finding
    // this avoids). The only thing the two mechanisms share is a READ of
    // `AgentEntry.last_progress_ms`, and this gate's skip path never writes to
    // it differently depending on the gate's verdict. So the direct proof: the
    // SAME agent, gated-and-skipped on `idle_tick_tick`, must still get a real
    // `compact_nudge_tick` fire in the same tick window — the skip has zero
    // effect on the coexisting mechanism.
    let (reg, _d) = test_registry();
    let g = reg
        .create_group(
            "C:/tmp/repo",
            Guardrails {
                intake_poll_minutes: Some(5),
                idle_tick_fallback_minutes: 180,
                compact_nudge_minutes: 20,
                compact_nudge_roles: vec!["orchestrator".to_string()],
                ..rails()
            },
        )
        .unwrap();
    let oid = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap().id;
    reg.set_autonomous(&g.id, true).unwrap();
    reg.seed_idle_tick_last_fired(&g.id, FAR);

    let empty = HashMap::new();
    let now = FAR + 15 * 60_000 + 1;
    assert!(reg.idle_tick_tick(now, &empty, &empty).is_empty(),
        "sanity: the intake gate must actually skip here (nothing new, fallback not due)");
    assert_eq!(
        reg.compact_nudge_tick(now, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()),
        vec![oid.clone()],
        "a gated idle-tick SKIP for this exact agent, at this exact tick, must not stop the \
         coexisting compact-nudge check from firing for it — the two are fully independent"
    );
}

#[test]
fn idle_tick_status_is_honest_about_latch_and_cap() {
    // rev-59 LOW: eligible_in_secs must never render a lying 0 while a non-time gate
    // (latch / per-hour cap) holds the tick. tick_status carries the honest reason.
    let (reg, _d, gid, oid) = autonomous_setup();
    let m = |t: u64| -> HashMap<String, u64> { [(oid.clone(), t)].into_iter().collect() };
    let none = HashMap::new();
    let win = 5 * 60_000u64; // default 5-min window, in ms

    // 1) Fresh: counting down toward the first tick.
    let s = reg.autonomy_state(&gid);
    assert_eq!(s["tick_status"], "counting_down");
    assert!(s["eligible_in_secs"].as_u64().unwrap() <= 5 * 60);

    // 2) After a tick fires the latch is set: waiting_for_activity, secs NULL — the
    //    core rev-59 case (a countdown here would hit 0 while nothing fires).
    assert_eq!(reg.idle_tick_tick(FAR, &none, &none), vec![oid.clone()]);
    let s = reg.autonomy_state(&gid);
    assert_eq!(s["tick_status"], "waiting_for_activity");
    assert!(s["eligible_in_secs"].is_null(), "a latched tick must not render a countdown");

    // 3) A real burst clears the latch and resets the clock so far in the (synthetic)
    //    past that it reads as eligible now.
    assert!(reg.idle_tick_tick(1_000, &m(100_000), &none).is_empty());
    let s = reg.autonomy_state(&gid);
    assert_eq!(s["tick_status"], "eligible");
    assert_eq!(s["eligible_in_secs"].as_u64().unwrap(), 0);

    // 4) Fill the per-hour cap to MAX_IDLE_TICKS_PER_HOUR (6). Step 2 already fired
    //    one, so 5 more here reach the cap. Each needs the latch cleared (a real
    //    burst that also resets the clock) then a full window of quiet.
    for i in 0..5u64 {
        let base = FAR + i * (win + 10);
        assert!(reg.idle_tick_tick(base, &m(1_000_000 + i * 100_000), &none).is_empty(),
            "burst i={i} resets, no fire");
        assert_eq!(reg.idle_tick_tick(base + win + 1, &none, &none), vec![oid.clone()],
            "a fresh window after the burst fires (i={i})");
    }
    // Cap now full; clear the last fire's latch with a burst (adds no tick_time) so
    // the CAP is the sole remaining gate.
    assert!(reg.idle_tick_tick(FAR + 100 * win, &m(9_000_000), &none).is_empty());
    let s = reg.autonomy_state(&gid);
    assert_eq!(s["tick_status"], "rate_capped", "cap full + latch clear → rate_capped");
    assert!(s["eligible_in_secs"].as_u64().is_some(),
        "rate_capped still yields a real (cap-based) countdown, not null");
}

#[test]
fn idle_tick_status_reports_paused_with_no_countdown() {
    // rev-59 re-check: autonomous and paused are INDEPENDENT markers. A paused
    // autonomous group suppresses all delivery, so the tick never fires — the panel
    // must not render a live countdown (the exact lying-countdown class).
    let (reg, _d, gid, _oid) = autonomous_setup();
    reg.pause_group(&gid).unwrap();
    let s = reg.autonomy_state(&gid);
    assert_eq!(s["tick_status"], "paused", "a paused autonomous group reports paused");
    assert!(s["eligible_in_secs"].is_null(), "paused must not render a ticking countdown");
    // Resuming restores a live countdown.
    reg.resume_group(&gid).unwrap();
    let s = reg.autonomy_state(&gid);
    assert_eq!(s["tick_status"], "counting_down", "resume restores the live countdown");
    assert!(s["eligible_in_secs"].as_u64().is_some());
}

// ---------- compact-nudge: periodic /compact at natural lulls (#287) ----------

/// Guardrails on Claude with compact-nudge set to `minutes` (0 = off) for the
/// given `roles` (lowercase `Role::as_str()` names), other fields mirroring
/// `rails()`.
fn compact_rails(minutes: u32, roles: &[&str]) -> Guardrails {
    Guardrails {
        compact_nudge_minutes: minutes,
        compact_nudge_roles: roles.iter().map(|s| s.to_string()).collect(),
        // #429: explicit opt-out — this helper is for compact-nudge/idle-tick
        // coexistence tests, not the intake gate; without this, `rails()`'s
        // unset `intake_poll_minutes` smart-defaults ON the moment
        // `set_autonomous` is called and a repeated idle-tick assertion below
        // would silently start exercising suppression instead.
        intake_poll_minutes: Some(0),
        ..rails()
    }
}

/// rev-42 delta (round 2): a `delivery_confirmations` map reporting a
/// CONFIRMED delivery to `agent_id` at `submit_sent_ms` — what a real
/// `deliver_prompt` background thread would eventually record, supplied
/// directly since unit tests have no live pty/app handle to exercise it for
/// real (see `DeliveryConfirmation`'s doc). `from: "loomux"` — every
/// existing caller uses this to simulate loomux's OWN reinjection delivery
/// confirming, never a human/other-agent message.
fn confirmed_delivery(agent_id: &str, submit_sent_ms: u64) -> HashMap<String, DeliveryConfirmation> {
    [(agent_id.to_string(), DeliveryConfirmation { submit_sent_ms, confirmed: true, from: "loomux".to_string() })]
        .into_iter()
        .collect()
}

/// Group with a live (Running, headless) orchestrator and compact-nudge
/// enabled for `minutes` on the default (orchestrator-only) role set. Returns
/// (reg, tempdir, group id, orchestrator id).
fn compact_nudge_setup(minutes: u32) -> (OrchRegistry, tempfile::TempDir, String, String) {
    let (reg, dir) = test_registry();
    let g = reg.create_group("C:/tmp/repo", compact_rails(minutes, &["orchestrator"])).unwrap();
    let o = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    (reg, dir, g.id, o.id)
}

#[test]
fn compact_nudge_role_gate_defaults_to_orchestrator_only() {
    let default_roles = vec!["orchestrator".to_string()];
    assert!(compact_nudge_role_allowed(Role::Orchestrator, &default_roles));
    assert!(!compact_nudge_role_allowed(Role::Worker, &default_roles),
        "workers are short-lived — not eligible unless explicitly configured");
    assert!(!compact_nudge_role_allowed(Role::Reviewer, &default_roles));
    assert!(!compact_nudge_role_allowed(Role::Planner, &default_roles));
    // Config-selectable: a group that opts a worker in gets exactly that.
    let widened = vec!["orchestrator".to_string(), "worker".to_string()];
    assert!(compact_nudge_role_allowed(Role::Worker, &widened));
    assert!(!compact_nudge_role_allowed(Role::Reviewer, &widened));
}

#[test]
fn compact_nudge_cli_gate_covers_claude_and_copilot() {
    // Both currently-supported CLIs have a real `/compact` command (Copilot's
    // confirmed via docs.github.com/en/copilot/reference/copilot-cli-reference/
    // cli-command-reference — an earlier round of this feature wrongly
    // asserted Copilot has none). Anything outside `SUPPORTED_CLIS` still
    // gets no nudge.
    assert!(compact_nudge_cli_supported("claude"));
    assert!(compact_nudge_cli_supported("copilot"));
    assert!(!compact_nudge_cli_supported("codex"));
    assert!(!compact_nudge_cli_supported(""));
}

#[test]
fn compact_nudge_defaults_off_and_orchestrator_only_and_zero_survives_clamping() {
    // The conservative shipped default: off, and — if ever turned on without an
    // explicit role list — orchestrator-only.
    let g = Guardrails::default().clamped();
    assert_eq!(g.compact_nudge_minutes, 0, "off by default");
    assert_eq!(g.compact_nudge_roles, vec!["orchestrator".to_string()]);
    // Unlike `idle_tick_minutes`, 0 here is a real "off", not "unset → default"
    // (there is no separate on/off marker) — clamped() must never float it up.
    let g = Guardrails { compact_nudge_minutes: 0, ..rails() }.clamped();
    assert_eq!(g.compact_nudge_minutes, 0);
    let g = Guardrails { compact_nudge_minutes: 99_999, ..rails() }.clamped();
    assert_eq!(g.compact_nudge_minutes, 1440, "clamps to the 24h ceiling");
    // Unrecognized role names are dropped and duplicates deduped; an all-bogus
    // list falls back to orchestrator-only rather than disabling every role.
    let g = Guardrails {
        compact_nudge_roles: vec!["bogus".into(), "worker".into(), "worker".into()],
        ..rails()
    }
    .clamped();
    assert_eq!(g.compact_nudge_roles, vec!["worker".to_string()]);
    let g = Guardrails { compact_nudge_roles: vec!["bogus".into()], ..rails() }.clamped();
    assert_eq!(g.compact_nudge_roles, vec!["orchestrator".to_string()]);
}

#[test]
fn compact_nudge_off_by_default_never_fires() {
    let (reg, _d, gid, _oid) = compact_nudge_setup(0);
    let empty = HashMap::new();
    assert!(reg.compact_nudge_tick(FAR, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty(),
        "compact_nudge_minutes 0 must never fire, no matter how long the pane is quiet");
    assert_eq!(audit_count(&reg, &gid, "compact-nudge"), 0);
}

#[test]
fn compact_nudge_fires_once_per_window_and_rearms_on_output() {
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let empty = HashMap::new();
    // Idle-at-prompt (output-quiet) far past the window → exactly one nudge,
    // audited, delivered via the same idleness signal idle-tick reads.
    assert_eq!(reg.compact_nudge_tick(FAR, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()), vec![oid.clone()],
        "an eligible pane quiet past the window must be nudged");
    assert_eq!(audit_count(&reg, &gid, "compact-nudge"), 1, "the nudge must be audited once");
    // Rate limit: still quiet, already latched → no second nudge in the same
    // window (this is also the "held is skipped, not queued" property at the
    // tick layer — there is no retry loop, just the one-shot latch).
    assert!(reg.compact_nudge_tick(FAR + 60_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty(), "one nudge per quiet window");
    // The pane produces real output (mid-turn / busy): clock + latch both
    // reset, and this very tick can't also fire — "never mid-turn" pinned
    // directly against the tick's own fire decision.
    let grew: HashMap<String, u64> = [(oid.clone(), 4096u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(FAR, &grew, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty(), "output growth is activity, not idle-at-prompt");
    // Quiet again shortly after: busy-then-quiet resolves (trusted arm) into
    // the delivery-confirmation phase — NOT itself a re-fire, and `compact_
    // pending` still gates the heuristic until that delivery confirms
    // (rev-42 delta, round 2).
    assert!(reg.compact_nudge_tick(FAR + 1_000, &grew, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty(),
        "resolving into the confirmation-wait phase is not itself a fire");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1, "the first arm's reinjection was attempted");
    assert!(reg.agent(&oid).unwrap().compact_pending, "still pending — waiting on confirmed delivery");
    // Confirm that delivery: the latch releases.
    let confirmed = confirmed_delivery(&oid, FAR + 1_000);
    assert!(reg.compact_nudge_tick(FAR + 2_000, &grew, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &confirmed).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending, "confirmed delivery releases the latch");
    // No further growth; a whole fresh window elapses (from the busy tick's
    // last_progress_ms) → a brand-new nudge.
    assert_eq!(reg.compact_nudge_tick(FAR + 20 * 60_000 + 1, &grew, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()), vec![oid.clone()],
        "a new quiet window after activity earns a new nudge");
    assert_eq!(audit_count(&reg, &gid, "compact-nudge"), 2);
}

#[test]
fn compact_nudge_ignores_subfloor_repaint_growth() {
    // Same repaint-vs-real-turn discrimination idle-tick uses (shared
    // `idle_activity_floor_bytes` guardrail, shared `idle_output_is_activity`):
    // a statusline/spinner frame must not indefinitely defer the nudge.
    let (reg, _d, _gid, oid) = compact_nudge_setup(5);
    let m = |total: u64| -> HashMap<String, u64> { [(oid.clone(), total)].into_iter().collect() };
    assert!(reg.compact_nudge_tick(1_000, &m(500), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty(), "an early sub-floor repaint is not a tick");
    assert_eq!(reg.compact_nudge_tick(FAR, &m(900), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()), vec![oid.clone()],
        "sub-floor creep never resets the clock, so the window still elapses");
}

/// Write a hook marker file with an EXPLICIT mtime, `offset_ms` (signed)
/// after `base_ms` (both real wall-clock ms since the epoch) — never a bare
/// `fs::write` right after spawning an agent, whose own `started_ms` is
/// sampled from the SAME real clock a few statements earlier: two real-clock
/// reads landing in the same millisecond (or a filesystem mtime-write
/// buffering delay) would otherwise make the product's `ts >= a.started_ms`
/// gate an intermittent test flake instead of a deterministic pass/fail.
fn write_hook_marker(path: &Path, base_ms: u64, offset_ms: i64) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    let f = fs::File::create(path).unwrap();
    let ms = (base_ms as i64 + offset_ms).max(0) as u64;
    f.set_modified(UNIX_EPOCH + Duration::from_millis(ms)).unwrap();
}

#[test]
fn compact_nudge_tick_treats_a_precompact_hook_marker_as_trusted_evidence() {
    // #417: a PreCompact hook marker (a marker FILE the generic hook script
    // writes — see `COMPACT_HOOK_SCRIPT`) is DIRECT evidence. It arms exactly
    // like the loomux-initiated path (trusted, no busy-then-quiet inference
    // gate) AND is treated as already busy — so with the pane already quiet
    // (no output growth), arm and resolve-into-reinjection happen on the
    // SAME tick, unlike a banner/manual inference arm which always needs a
    // later quiet observation.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty = HashMap::new();

    // No marker yet: an ordinary quiet tick fires nothing (the heuristic
    // window is 20 minutes away; nothing else armed it either).
    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending);

    // Simulate the hook firing: write the marker the script would have.
    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    // The marker arms AND resolves in this one tick (loomux pasted nothing
    // itself, so this is not a "nudge"; the reinjection notice is a separate
    // `deliver_prompt`, not something `compact_nudge_tick`'s return value
    // reports).
    assert!(reg.compact_nudge_tick(2_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 1, "the arm itself is audited, distinctly from the reinjection");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "still pending — waiting on confirmed delivery");
    assert!(a.compact_reinject_attempted_ms.is_some(), "moved into the delivery-confirmation phase");
    assert_eq!(a.compact_pending_evidence, Some("hook"), "the evidence tag survives into that phase");

    // Confirm delivery: the arm resolves and the evidence tag clears.
    let confirmed = confirmed_delivery(&oid, 2_000);
    assert!(reg.compact_nudge_tick(3_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &confirmed).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "confirmed delivery releases the latch");
    assert_eq!(a.compact_pending_evidence, None, "cleared on resolution, like the trust flag it rides alongside");

    // The SAME marker (unchanged mtime) must never re-arm.
    assert!(reg.compact_nudge_tick(4_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending, "a stale, already-consumed marker must not re-arm");
}

#[test]
fn compact_nudge_tick_treats_a_sessionstart_hook_marker_as_an_immediate_confirm() {
    // #417: the SessionStart(compact) marker is even STRONGER direct proof —
    // Claude Code itself restarted the session specifically because of a
    // compact — so it arms AND confirms in one step, unconditionally (unlike
    // the PreCompact marker, which only arms while nothing is already
    // pending). This covers a hook config with only SessionStart wired, or a
    // PreCompact marker a tick loop raced past.
    //
    // rev-4 review (N3): the SessionStart hook is also the ONE script branch
    // that emits native `additionalContext` (see `COMPACT_HOOK_SCRIPT`) — so
    // Claude Code has ALREADY re-grounded the agent by the time this marker
    // is observed. loomux's OWN reinjection is therefore skipped entirely
    // here (a double re-grounding would spend exactly the tokens native
    // delivery exists to save) — this resolves straight to `compact_pending
    // = false`, not into the delivery-confirmation phase.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty = HashMap::new();

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.sessionstart-compact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "native re-grounding already landed — nothing left pending");
    assert!(a.compact_reinject_attempted_ms.is_none(), "no loomux-side delivery to confirm");
    assert_eq!(a.compact_pending_evidence, None, "cleared on this terminal resolution");
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 1, "the arm is still audited");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 0, "no duplicate re-grounding is pasted");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-skipped-native"), 1);
}

#[test]
fn compact_nudge_tick_sessionstart_evidence_resolves_even_while_the_pane_is_busy() {
    // Round 7, the live-demo incident reproduced directly: both hooks fired
    // for real, N3 suppression correctly held (no reinjection), but the
    // lifecycle badge then showed "compact timed out (no evidence)" anyway.
    // Root cause — the SessionStart resolution used to be nested inside
    // `else if currently_quiet`, so it only took effect on a tick where the
    // pane happened to show NO growth. A fast compact whose agent keeps
    // working continuously afterward (this test's shape: real, large output
    // growth on the SAME tick the marker is consumed) never satisfies that,
    // and `compact-arm-timeout` fires instead at precisely `ARM_PENDING_
    // TIMEOUT_MS` after the precompact arm — exactly the incident's audit
    // timeline. SessionStart evidence must resolve unconditionally: it is
    // proof the compaction already finished AND that native re-grounding
    // already reached the agent, so there is nothing left for a quiet
    // observation to confirm.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.sessionstart-compact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    // The pane is BUSY on this exact tick — real growth well past any
    // activity floor, i.e. `currently_quiet` is false.
    let busy: HashMap<String, u64> = [(oid.clone(), 500_000u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(1_000, &busy, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "resolves regardless of busy/quiet — there is no confirmation left to wait on");
    assert_eq!(a.compact_pending_evidence, None);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-skipped-native"), 1);
    assert_eq!(audit_count(&reg, &gid, "compact-arm-timeout"), 0);

    // The agent then keeps being busy for well past ARM_PENDING_TIMEOUT_MS
    // (5 minutes) — since the arm already resolved, this must never trip
    // the timeout the incident's audit log showed firing.
    let still_busy: HashMap<String, u64> = [(oid.clone(), 2_000_000u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(1_000 + 6 * 60_000, &still_busy, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-arm-timeout"), 0, "already resolved — nothing left to time out");
}

#[test]
fn compact_nudge_tick_fast_compact_both_hook_events_in_one_poll_gap_resolves_not_abandoned() {
    // Round 7: the OTHER real-world shape from the same incident — a fast
    // compaction where both PreCompact and SessionStart markers already
    // exist by the time loomux's tick loop gets around to polling (a slow
    // poll cadence, or a compaction fast enough to finish between two
    // ticks). Both markers land in the SAME `compact_nudge_tick` call: the
    // PreCompact block arms, then the SessionStart block — running right
    // after it, same iteration — resolves immediately. Must never leave
    // `compact_pending` open long enough to reach `ARM_PENDING_TIMEOUT_MS`.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;

    let precompact_marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    let sessionstart_marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.sessionstart-compact.json"));
    write_hook_marker(&precompact_marker, started_ms, 1_000);
    write_hook_marker(&sessionstart_marker, started_ms, 1_000);

    let empty = HashMap::new();
    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "both events land, then resolve, in the SAME tick");
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 2, "both arm events are still individually audited");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-skipped-native"), 1, "exactly one terminal resolution, not one per event");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 0);

    // Ticking well past ARM_PENDING_TIMEOUT_MS must never abandon something
    // that already resolved.
    assert!(reg.compact_nudge_tick(1_000 + 6 * 60_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-arm-timeout"), 0);
}

#[test]
fn compact_nudge_tick_sessionstart_evidence_after_a_reinject_was_already_decided_clears_the_confirmation_phase() {
    // rev-10 review (B1, blocking), round 7: the SessionStart terminal path
    // runs BEFORE the delivery-confirmation block, every tick — reachable
    // ordering matching the incident's own ~2-minute gap: a PreCompact arm
    // resolves into a DECIDED loomux reinjection (busy-then-quiet, trusted)
    // before any SessionStart marker exists, then the SessionStart marker
    // lands on a LATER tick. If the SessionStart block only cleared the arm
    // fields (not `compact_reinject_attempted_ms`/`attempts`), the
    // confirmation phase stayed live against a `compact_pending` it had
    // already reset to `false` — retrying, double-confirming, or falsely
    // abandoning a compaction that in fact succeeded via native evidence.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty = HashMap::new();

    // Arm via PreCompact, quiet immediately — resolves into a DECIDED
    // loomux reinjection on this same tick (same shape as `compact_nudge_
    // tick_a_precompact_only_arm_still_gets_loomuxs_own_reinjection`).
    let precompact_marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&precompact_marker, started_ms, 1_000);
    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "still pending — waiting on the reinjection's own delivery to confirm");
    assert!(a.compact_reinject_attempted_ms.is_some(), "a loomux reinjection was already DECIDED");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);

    // SessionStart evidence lands later — the delivery-confirmation phase
    // is still live (no `confirmed` delivery map passed) when it does.
    let sessionstart_marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.sessionstart-compact.json"));
    write_hook_marker(&sessionstart_marker, started_ms, 120_000);
    assert!(reg.compact_nudge_tick(121_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "the sessionstart terminal path resolves it");
    assert!(a.compact_reinject_attempted_ms.is_none(), "B1: the confirmation-phase bookkeeping must clear too");
    assert_eq!(a.compact_reinject_attempts, 0);
    // The reinjection prompt already went out (attempt #1, above) — that
    // was not "skipped", so it must not be double-counted as a fresh
    // native-skip.
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-skipped-native"), 0);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1, "no retry");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-confirmed"), 0, "no stale double-confirm");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-abandoned"), 0);

    // A late-arriving confirmation for the ORIGINAL (now-cleared) attempt
    // must not resurrect the confirmation phase.
    let late_confirm = confirmed_delivery(&oid, 1_000);
    assert!(reg.compact_nudge_tick(122_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &late_confirm).is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-confirmed"), 0, "nothing left to confirm");

    // Ticking well past ARM_PENDING_TIMEOUT_MS must never falsely abandon a
    // compaction that already resolved via native evidence.
    assert!(reg
        .compact_nudge_tick(121_000 + 6 * 60_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new())
        .is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-arm-timeout"), 0);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-abandoned"), 0);

    // A genuinely NEW compaction can still re-arm cleanly — the state
    // machine is not wedged.
    write_hook_marker(&precompact_marker, started_ms, 121_000 + 6 * 60_000 + 1_000);
    assert!(reg
        .compact_nudge_tick(121_000 + 6 * 60_000 + 2_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new())
        .is_empty());
    assert!(reg.agent(&oid).unwrap().compact_pending, "a fresh marker can re-arm a new cycle");
}

#[test]
fn compact_nudge_tick_a_precompact_only_arm_still_gets_loomuxs_own_reinjection() {
    // rev-4 review (N3): the fallback half of the same fix. A PreCompact
    // marker with NO SessionStart marker (a hook config that only wires the
    // one event, or a SessionStart marker this tick loop simply hasn't seen
    // yet) never delivered native `additionalContext` — the script's
    // `precompact` branch only ever writes a marker, nothing else — so
    // loomux's own reinjection must still fire. Never silently drop the ONLY
    // re-grounding channel just because SOME hook evidence exists.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty = HashMap::new();

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "still pending — waiting on the reinjection's own delivery to confirm");
    assert!(a.compact_reinject_attempted_ms.is_some());
    assert_eq!(a.compact_pending_evidence, Some("hook"));
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1, "the ONLY re-grounding channel available must still fire");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-skipped-native"), 0);
}

#[test]
fn compact_nudge_tick_ignores_a_hook_marker_older_than_the_agent_itself() {
    // rev-4 review (B1, blocking): the exact failure sequence a live restart
    // can hit. `compact_hook_*_seen_ms` is in-memory (resets to `None` on a
    // fresh `AgentEntry`), and agent ids come from an in-memory counter too
    // — so a fresh boot can mint an id a PREVIOUS process already used,
    // while the group's `hooks/` marker files (on disk) survive the
    // restart untouched. Without the `ts > a.started_ms` gate, the very
    // first tick after such a restart would read the OLD process's marker
    // as "fresh evidence" (`ts > None.unwrap_or(0)` is true for any real
    // mtime) and arm TRUSTED with no compaction having happened at all.
    // Uses the PreCompact marker specifically (not SessionStart): #417's N3
    // fix resolves a fresh SessionStart marker straight to a terminal state
    // in the SAME tick (native re-grounding already delivered — see
    // `compact_nudge_tick_treats_a_sessionstart_hook_marker_as_an_immediate_
    // confirm`), which would make this test's own "still arms normally"
    // half read the wrong signal. PreCompact's arm-then-wait-for-delivery
    // shape keeps this test's B1 story (the `started_ms` gate itself)
    // decoupled from N3's separate concern.
    let (reg, _d, gid, oid) = compact_nudge_setup(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    fs::create_dir_all(marker.parent().unwrap()).unwrap();
    let f = fs::File::create(&marker).unwrap();
    // Backdate the marker to well before this agent's own `started_ms` —
    // exactly the shape of one surviving from a PREVIOUS process.
    f.set_modified(UNIX_EPOCH + Duration::from_millis(started_ms.saturating_sub(60_000))).unwrap();
    drop(f);

    let empty = HashMap::new();
    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "a marker older than the agent's own started_ms must never arm");
    assert_eq!(a.compact_pending_evidence, None);
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 0);
    // Never treated as evidence at all, so never consumed either.
    assert!(marker.exists(), "a rejected stale marker is left alone, not silently deleted");

    // A GENUINELY fresh marker (mtime after started_ms) from the SAME agent
    // still arms normally — the fix excludes only markers that PREDATE it.
    // Mtime set explicitly (not just "written just now") so this assertion
    // can never flake on two real-clock reads landing in the same
    // millisecond as `started_ms` itself.
    let f = fs::File::create(&marker).unwrap();
    f.set_modified(UNIX_EPOCH + Duration::from_millis(started_ms + 1_000)).unwrap();
    drop(f);
    assert!(reg.compact_nudge_tick(2_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "a marker written during this agent's own lifetime still arms");
    assert_eq!(a.compact_pending_evidence, Some("hook"));
    assert!(!marker.exists(), "delete-on-consume: an ACTUALLY-used marker is removed from disk");
}

// ─────────────── #417 correction round: Copilot's own PreCompact hook ───────────────
//
// An earlier round of this feature wrongly asserted Copilot has no compaction hooks at
// all upstream. It does: `preCompact` (docs.github.com/en/copilot/reference/hooks-
// reference), with a payload nearly identical to Claude's. What it does NOT have is any
// `sessionStart` source value indicating a post-compaction resume (`source` is exactly
// `"startup" | "resume" | "new"` — confirmed by the docs, not ambiguous) or a
// `postCompact` event of any kind — so Copilot gets the TRUSTED ARM half of #417
// (`compact_pending_trusted = true`, same as Claude's own `precompact`-only case) but
// never the native-`additionalContext` / N3-suppression half, which stays Claude-only.
// The marker-consumption path itself (the B1 fix: `ts >= a.started_ms`, delete-on-
// consume) is CLI-agnostic — it reads `<group_dir>/hooks/<agent_id>.precompact.json`
// with no idea which CLI wrote it, so the tests below reuse it unchanged; only the
// SETUP (a copilot-CLI group) and the one new CLI-admission gate differ from the
// Claude tests above.

fn compact_copilot_rails(minutes: u32, roles: &[&str]) -> Guardrails {
    Guardrails {
        compact_nudge_minutes: minutes,
        compact_nudge_roles: roles.iter().map(|s| s.to_string()).collect(),
        ..copilot_rails()
    }
}

fn compact_nudge_setup_copilot(minutes: u32) -> (OrchRegistry, tempfile::TempDir, String, String) {
    let (reg, dir) = test_registry();
    let g = reg.create_group("C:/tmp/copilot-repo", compact_copilot_rails(minutes, &["orchestrator"])).unwrap();
    let o = reg.spawn_agent(&g.id, Role::Orchestrator, "orch", "", false, None).unwrap();
    (reg, dir, g.id, o.id)
}

#[test]
fn copilot_precompact_hook_marker_is_trusted_evidence_too() {
    // Same evidence class as Claude's `precompact` case (`compact_pending_trusted =
    // true`) — a hook telling loomux a compaction is starting is equally trustworthy
    // regardless of which CLI's hook fired it. Before #417's CLI-gate widening
    // (`compact_nudge_cli_supported`), a copilot agent never even reached this code —
    // the per-agent loop's admission gate used to be claude-only, so this marker
    // would have been silently ignored forever.
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty = HashMap::new();

    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending);

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    // Arms AND resolves into the delivery-confirmation phase on this one tick — a
    // Copilot precompact arm has no native re-grounding to make redundant (unlike a
    // Claude SessionStart-confirmed one), so loomux's OWN reinjection is the only
    // re-grounding channel here, same as Claude's precompact-only case.
    assert!(reg.compact_nudge_tick(2_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 1);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection-skipped-native"), 0);
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "still pending — waiting on confirmed delivery");
    assert!(a.compact_reinject_attempted_ms.is_some());
    assert_eq!(a.compact_pending_evidence, Some("hook"));

    let confirmed = confirmed_delivery(&oid, 2_000);
    assert!(reg.compact_nudge_tick(3_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &confirmed).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending);
}

#[test]
fn copilot_precompact_marker_gets_the_same_b1_restart_protection() {
    // The exact B1 regression, replayed for a Copilot marker — "one mechanism, two
    // writers" only actually holds if the SAME gate protects both.
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    fs::create_dir_all(marker.parent().unwrap()).unwrap();
    let f = fs::File::create(&marker).unwrap();
    f.set_modified(UNIX_EPOCH + Duration::from_millis(started_ms.saturating_sub(60_000))).unwrap();
    drop(f);

    let empty = HashMap::new();
    assert!(reg.compact_nudge_tick(1_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending, "a marker older than started_ms must never arm, Copilot included");
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 0);
    assert!(marker.exists());
}

#[test]
fn copilot_compaction_marker_resolves_the_arm_even_while_the_pane_stays_busy() {
    // #428 (round 9): the exact live-incident shape, reproduced. Marker
    // text is quoted directly from the issue's own report of the user's
    // live observation (its body and comment), not reconstructed from
    // memory. Continuously busy every tick (never quiet) is the fast-path
    // proof: this must be a TERMINAL path resolved at marker-consume, not
    // merely a faster busy-then-quiet that happened to get lucky.
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty_tail: HashMap<String, (String, u64)> = HashMap::new();

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    // Arm: precompact evidence, pane already busy — matches the issue's
    // own "+0s" timeline.
    let busy: HashMap<String, u64> = [(oid.clone(), 500_000u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(1_000, &busy, &empty_tail, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "armed, waiting on resolution");
    assert!(a.compact_reinject_attempted_ms.is_none(), "not yet decided — no marker seen yet");

    // The marker appears now — resolved on THIS tick, with the pane STILL
    // busy (never went quiet in between).
    let tail_with_marker: HashMap<String, (String, u64)> = [(
        oid.clone(),
        ("A new checkpoint has been added to your session.".to_string(), 2_000),
    )]
    .into_iter()
    .collect();
    let still_busy: HashMap<String, u64> = [(oid.clone(), 900_000u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(2_000, &still_busy, &tail_with_marker, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "still pending — waiting on the reinjection's own delivery to confirm");
    assert!(
        a.compact_reinject_attempted_ms.is_some(),
        "the marker decided a reinjection immediately — no quiet tick needed"
    );
    assert_eq!(a.compact_reinject_attempts, 1);
    assert_eq!(audit_count(&reg, &gid, "compact-resolved-copilot-marker"), 1);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);
    assert_eq!(audit_count(&reg, &gid, "compact-arm-timeout"), 0);
    // rev-21 review: this path must reset the SAME fields the sibling
    // busy-then-quiet "confirmed" branch resets, no more — `compact_
    // pending_evidence` (the "hook" chip label) stays put through the
    // confirmation phase either way, so which path resolved the arm never
    // changes what the badge shows afterward.
    assert_eq!(a.compact_pending_evidence, Some("hook"), "the hook chip label must survive into the confirmation phase");

    // Ticking well past ARM_PENDING_TIMEOUT_MS (5 min), still no marker,
    // still busy — must never time out something already resolved. Also
    // proves the delivery-confirmation phase (not this new block) is what
    // now owns resolution — exactly like every other terminal path.
    let confirmed = confirmed_delivery(&oid, 2_000);
    assert!(reg
        .compact_nudge_tick(2_000 + 6 * 60_000, &still_busy, &empty_tail, &HashMap::new(), &HashMap::new(), &HashMap::new(), &confirmed)
        .is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-arm-timeout"), 0);
    assert!(!reg.agent(&oid).unwrap().compact_pending, "confirmed delivery resolves it cleanly");
}

#[test]
fn copilot_compaction_marker_with_no_arm_is_a_no_op() {
    // #428, the B1-shaped safety check: a marker sighting alone must never
    // conjure an arm out of nothing. The whole block is gated on `a.
    // compact_pending`, which nothing here can set `true` from `false` —
    // a stale mention from a long-past, already-resolved compaction
    // sitting in scrollback must never resurrect anything.
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(20);
    let tail_with_marker: HashMap<String, (String, u64)> =
        [(oid.clone(), ("Compaction completed".to_string(), 1_000))].into_iter().collect();
    let empty: HashMap<String, u64> = HashMap::new();
    assert!(reg.compact_nudge_tick(1_000, &empty, &tail_with_marker, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(!a.compact_pending, "no arm existed — the marker alone must never create one");
    assert_eq!(audit_count(&reg, &gid, "compact-resolved-copilot-marker"), 0);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 0);
}

#[test]
fn copilot_compaction_marker_while_a_reinjection_is_already_in_flight_is_a_no_op() {
    // rev-10's B1 lesson, applied to the new terminal path: once busy-
    // then-quiet already decided a reinjection (`compact_reinject_
    // attempted_ms` is `Some`), a LATER marker sighting for the SAME cycle
    // must never re-decide or reset it — no double dispatch, no lost
    // attempt count, no fresh audit line for something that was already
    // resolved.
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty_outputs: HashMap<String, u64> = HashMap::new();
    let empty_tail: HashMap<String, (String, u64)> = HashMap::new();

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    // Arm + quiet resolves into the confirmation phase via ordinary
    // busy-then-quiet, same shape as `copilot_precompact_hook_marker_is_
    // trusted_evidence_too`.
    assert!(reg.compact_nudge_tick(1_000, &empty_outputs, &empty_tail, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert!(reg.compact_nudge_tick(2_000, &empty_outputs, &empty_tail, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_reinject_attempted_ms.is_some(), "already decided via busy-then-quiet");
    assert_eq!(a.compact_reinject_attempts, 1);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);

    // The marker appears NOW, for the same still-open cycle, delivery not
    // yet confirmed.
    let tail_with_marker: HashMap<String, (String, u64)> =
        [(oid.clone(), ("Compaction completed".to_string(), 3_000))].into_iter().collect();
    assert!(reg.compact_nudge_tick(3_000, &empty_outputs, &tail_with_marker, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert_eq!(a.compact_reinject_attempts, 1, "must not double-dispatch");
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1, "no second reinjection");
    assert_eq!(
        audit_count(&reg, &gid, "compact-resolved-copilot-marker"), 0,
        "already in flight — this is a no-op, not a fresh resolution"
    );
}

#[test]
fn copilot_busy_then_quiet_still_resolves_when_the_marker_never_appears() {
    // #428 regression pin: the marker is an ACCELERATOR, not a
    // replacement — with no marker ever painted (a future Copilot build
    // changed the wording, or this tick's read simply missed it), the
    // pre-existing busy-then-quiet resolution must keep working exactly
    // as it did before this round.
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(20);
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let empty_tail: HashMap<String, (String, u64)> = HashMap::new();

    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    write_hook_marker(&marker, started_ms, 1_000);

    let busy: HashMap<String, u64> = [(oid.clone(), 500_000u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(1_000, &busy, &empty_tail, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert!(reg.agent(&oid).unwrap().compact_reinject_attempted_ms.is_none(), "not yet — no marker, no quiet tick yet");

    // The pane goes quiet (same total as the last baseline = no growth) —
    // busy-then-quiet resolves it, unchanged from before this round.
    let quiet: HashMap<String, u64> = [(oid.clone(), 500_000u64)].into_iter().collect();
    assert!(reg.compact_nudge_tick(2_000, &quiet, &empty_tail, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_reinject_attempted_ms.is_some(), "busy-then-quiet still resolves with no marker present");
    assert_eq!(audit_count(&reg, &gid, "compact-resolved-copilot-marker"), 0);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);
}

#[test]
fn compact_nudge_tick_does_paste_slash_compact_into_a_copilot_pane() {
    // #417 correction round 2: an earlier round of this feature asserted
    // Copilot has no `/compact` command at all and pinned a NEGATIVE test
    // here proving loomux must never paste it into a Copilot pane. That
    // claim was wrong — GitHub's own CLI command reference documents
    // `/compact [FOCUS-INSTRUCTIONS]` as a real Copilot CLI command,
    // identical in spirit to Claude's — so this test now inverts to prove
    // the OPPOSITE: a copilot agent quiet past the heuristic window DOES get
    // nudged with a real `/compact` paste, exactly like a Claude agent would.
    let (reg, _d, _gid, oid) = compact_nudge_setup_copilot(1);
    let empty = HashMap::new();
    assert_eq!(
        reg.compact_nudge_tick(FAR, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()),
        vec![oid.clone()],
        "a copilot agent quiet past the heuristic window gets the same /compact paste a Claude agent would"
    );
    assert!(reg.agent(&oid).unwrap().compact_pending);
}

#[test]
fn compact_nudge_tick_copilot_full_loop_paste_then_hook_confirms_then_reinjects() {
    // #417 correction round 2, the FULL loop this correction completes for
    // Copilot, in its two independent halves — exactly mirroring how the
    // pre-existing Claude tests cover the same two halves separately
    // (`compact_nudge_tick_reinjects_after_a_loomux_initiated_fire_too` and
    // `compact_nudge_tick_treats_a_precompact_hook_marker_as_trusted_
    // evidence`), now proven back-to-back for the SAME copilot agent:
    //
    // Half 1 — loomux-initiated: the heuristic fire pastes `/compact` into
    // the copilot pane (now possible — see the test above); this arm is
    // trusted by PROVENANCE alone (loomux has positive knowledge the
    // command was submitted — the rev-42 delta), so it resolves via
    // busy-then-quiet, with no hook marker needed at all.
    //
    // Half 2 — hook-initiated: independently of anything loomux pasted,
    // Copilot's own `preCompact` hook can fire for a real compaction (an
    // autonomous auto-compact, or a human-typed `/compact` loomux's manual
    // detector missed) and the marker is TRUSTED evidence on its own,
    // arming AND resolving into the delivery-confirmation phase in one
    // tick — loomux's own reinjection is the only re-grounding channel
    // (Copilot has no native additionalContext path for compaction, unlike
    // Claude's SessionStart branch).
    let (reg, _d, gid, oid) = compact_nudge_setup_copilot(5);
    let empty = HashMap::new();

    // Half 1: heuristic fire pastes /compact, then resolves via busy-then-quiet.
    assert_eq!(
        reg.compact_nudge_tick(FAR, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()),
        vec![oid.clone()],
        "the heuristic fire pastes /compact itself"
    );
    assert!(reg.agent(&oid).unwrap().compact_pending);
    assert_eq!(audit_count(&reg, &gid, "compact-nudge"), 1);
    let baseline: HashMap<String, u64> = [(oid.clone(), 100_000u64)].into_iter().collect();
    let grew: HashMap<String, u64> = [(oid.clone(), 50_000u64)].into_iter().collect();
    let dropped: HashMap<String, u64> = [(oid.clone(), 5_000u64)].into_iter().collect();
    let _ = reg.compact_nudge_tick(FAR + 1_000, &grew, &HashMap::new(), &HashMap::new(), &baseline, &HashMap::new(), &HashMap::new());
    let _ = reg.compact_nudge_tick(FAR + 2_000, &grew, &HashMap::new(), &HashMap::new(), &dropped, &HashMap::new(), &HashMap::new());
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 1);
    let confirmed = confirmed_delivery(&oid, FAR + 2_000);
    let _ = reg.compact_nudge_tick(FAR + 3_000, &grew, &HashMap::new(), &HashMap::new(), &dropped, &HashMap::new(), &confirmed);
    assert!(!reg.agent(&oid).unwrap().compact_pending, "half 1 resolved cleanly before half 2 starts");

    // Half 2: Copilot's own preCompact hook fires independently and writes
    // the marker `ensure_copilot_compact_hook`'s script provisions — the
    // SAME marker-consumption path Claude's hook uses, CLI-agnostic by design.
    let started_ms = reg.agent(&oid).unwrap().started_ms;
    let marker = reg.state_root().join(&gid).join("hooks").join(format!("{oid}.precompact.json"));
    // The marker-arm gate only ever compares `ts` against `started_ms` and
    // the last-seen marker ts, never against `now` — so the mtime stays a
    // small, real offset from `started_ms` (matching every other marker
    // test) even while `now` keeps advancing on the FAR-scale clock half 1
    // already established.
    write_hook_marker(&marker, started_ms, 1_000);

    assert!(reg.compact_nudge_tick(FAR + 4_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new()).is_empty());
    assert_eq!(audit_count(&reg, &gid, "compact-hook-evidence"), 1);
    assert_eq!(audit_count(&reg, &gid, "compact-reinjection"), 2, "the second, hook-confirmed cycle reinjects too");
    let a = reg.agent(&oid).unwrap();
    assert!(a.compact_pending, "still pending — waiting on confirmed delivery");
    assert_eq!(a.compact_pending_evidence, Some("hook"));

    let confirmed2 = confirmed_delivery(&oid, FAR + 4_000);
    assert!(reg.compact_nudge_tick(FAR + 5_000, &empty, &HashMap::new(), &HashMap::new(), &HashMap::new(), &HashMap::new(), &confirmed2).is_empty());
    assert!(!reg.agent(&oid).unwrap().compact_pending, "the full detection/recovery loop resolves cleanly, both halves");
}

#[test]
fn ensure_copilot_compact_hook_writes_an_additive_generic_precompact_entry() {
    // Copilot's own docs confirm multiple hook-config sources are MERGED — "When
    // the same event appears in multiple sources, all hook entries from all
    // sources are run" — so writing this file is proven safe against a user's own
    // hooks, unlike Claude's `--settings` (whose merge semantics this repo could
    // not verify empirically). Written to the SAME user-level directory Copilot
    // itself auto-loads (no CLI flag needed), never the repo's `.github/hooks/`.
    let (reg, dir) = test_registry();
    let g = reg.create_group("C:/tmp/copilot-repo", copilot_rails()).unwrap();
    reg.spawn_agent(&g.id, Role::Worker, "w", "t", false, None).unwrap();

    let cfg_path = dir.path().join("copilot-hooks").join("loomux-compact.json");
    let cfg: Value = serde_json::from_str(&fs::read_to_string(&cfg_path).unwrap()).unwrap();
    assert_eq!(cfg["version"], json!(1));
    let entry = &cfg["hooks"]["preCompact"][0];
    assert_eq!(entry["type"], json!("command"));
    // Both variants always provided — Copilot itself picks the one for its host
    // OS; loomux never resolves its own interpreter path for Copilot (unlike
    // Claude's hook command, which bakes in an absolute `sh.exe`).
    let bash = entry["bash"].as_str().unwrap();
    let ps1 = entry["powershell"].as_str().unwrap();
    assert!(bash.contains("LOOMUX_GROUP_DIR") && bash.contains("LOOMUX_AGENT_ID"), "{bash}");
    assert!(ps1.contains("LOOMUX_GROUP_DIR") && ps1.contains("LOOMUX_AGENT_ID"), "{ps1}");
    assert!(bash.contains("precompact.json") && ps1.contains("precompact.json"));

    // No payload parsing happens on loomux's side at all — the script only ever
    // reads its OWN inherited environment (never Copilot's camelCase/snake_case
    // JSON piped to stdin), so there is no casing distinction for loomux's code
    // to get wrong. That's a deliberate simplification: the marker's mere
    // existence is the whole signal (`read_hook_marker_ts` reads the FILE's own
    // mtime), so nothing here needs to understand the event's payload shape.

    // A Claude-CLI group must never get this file at all.
    let (reg2, dir2) = test_registry();
    let g2 = reg2.create_group("C:/tmp/claude-repo", rails()).unwrap();
    reg2.spawn_agent(&g2.id, Role::Worker, "w", "t", false, None).unwrap();
    assert!(!dir2.path().join("copilot-hooks").join("loomux-compact.json").exists());
}

#[test]
fn ensure_copilot_compact_hook_also_writes_the_promptsubmit_entry() {
    // #112: the real prompt-landed signal rides the SAME global file
    // alongside `preCompact` (still one small additive file — Copilot's own
    // "all hook entries from all sources are run" guarantee covers both
    // events identically).
    let (reg, dir) = test_registry();
    let g = reg.create_group("C:/tmp/copilot-repo", copilot_rails()).unwrap();
    reg.spawn_agent(&g.id, Role::Worker, "w", "t", false, None).unwrap();

    let cfg_path = dir.path().join("copilot-hooks").join("loomux-compact.json");
    let cfg: Value = serde_json::from_str(&fs::read_to_string(&cfg_path).unwrap()).unwrap();
    // preCompact must be completely untouched by this addition.
    assert!(cfg["hooks"]["preCompact"][0]["bash"].as_str().unwrap().contains("precompact.json"));

    let entry = &cfg["hooks"]["userPromptSubmitted"][0];
    assert_eq!(entry["type"], json!("command"));
    let bash = entry["bash"].as_str().unwrap();
    let ps1 = entry["powershell"].as_str().unwrap();
    assert!(bash.contains("LOOMUX_GROUP_DIR") && bash.contains("LOOMUX_AGENT_ID"), "{bash}");
    assert!(ps1.contains("LOOMUX_GROUP_DIR") && ps1.contains("LOOMUX_AGENT_ID"), "{ps1}");
    // Existence-only: the marker path is `.promptsubmit.jsonl` (same file the
    // Claude script writes real JSON records into), but this command never
    // reads Copilot's own payload — the docs don't nail down its transport
    // for this event (unlike Claude's stdin-JSON contract). Confirmed by
    // there being no field-name text (`user_input`/`prompt`/etc) anywhere in
    // either command string — the whole point of `PromptSubmitRecord::text`
    // being `None` for a Copilot record.
    assert!(bash.contains("promptsubmit.jsonl") && ps1.contains("promptsubmit.jsonl"));
    for field in ["user_input", "user_prompt", "\"prompt\"", "stdin", "ReadToEnd"] {
        assert!(!bash.contains(field) && !ps1.contains(field), "no payload read attempted: field={field} bash={bash} ps1={ps1}");
    }
}

// ───────── rev-4 review round 3: PreCompact can BLOCK compaction — exit-0 safety ─────────
//
// Claude's own hooks reference (code.claude.com/docs/en/hooks) confirms `PreCompact` is a
// BLOCKING event: exit code 2 (or `{"decision":"block"}`) prevents the compaction from
// happening at all. Copilot's reference documents the same for its own `preCompact`. A
// marker-write failure (a full disk, a permissions problem, a path collision) must degrade
// to "no hook signal, the inference tier still catches it" — NEVER to "the user's
// compaction silently didn't happen." These tests run the ACTUAL generated script/command
// text under an induced failure and assert the real process exit code, rather than
// reasoning about shell semantics from the Rust side only.

/// `sh` to run a hook script with — `locate_sh_exe`'s absolute Windows path, or a bare `sh`
/// (a POSIX guarantee) everywhere else. `None` only when Windows genuinely has no `sh.exe`
/// anywhere (same "skip, don't fail" precedent as the #335 shim tests).
fn resolve_test_sh() -> Option<String> {
    #[cfg(windows)]
    {
        locate_sh_exe()
    }
    #[cfg(not(windows))]
    {
        Some("sh".to_string())
    }
}

#[test]
fn compact_hook_script_sh_exits_zero_when_the_marker_dir_cant_be_created() {
    let Some(sh) = resolve_test_sh() else {
        eprintln!("SKIP compact_hook_script_sh_exits_zero_when_the_marker_dir_cant_be_created: no sh found");
        return;
    };
    let td = tempfile::tempdir().unwrap();
    // A regular FILE occupying the path the script wants to `mkdir -p` a
    // subdirectory under — fails `mkdir -p "$group_dir/hooks"` portably, with
    // no reliance on chmod/permission APIs (unreliable to set up on Windows).
    let blocked_group_dir = td.path().join("blocked-group-dir");
    fs::write(&blocked_group_dir, "occupies the path; not a directory").unwrap();
    let script_path = td.path().join("compact-hook.sh");
    fs::write(&script_path, COMPACT_HOOK_SCRIPT).unwrap();

    for event in ["precompact", "sessionstart-compact"] {
        let output = std::process::Command::new(&sh)
            .arg(&script_path)
            .arg(event)
            .arg(blocked_group_dir.display().to_string())
            .arg("agent-1")
            .output()
            .expect("sh must run");
        assert_eq!(
            output.status.code(),
            Some(0),
            "event={event}: the hook must never fail PreCompact's blocking lifecycle event just \
             because its own marker write failed — stdout={:?} stderr={:?}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr),
        );
    }
}

